// testgen.t27 -- Generic Test Generator for TDD-Inside-Spec
// Generates test code from spec test blocks for multiple backends

module testgen {
    using ast: @import("../../ast.t27");

    // TestGen options
    pub const TestGenOptions = struct {
        backend: []const u8,           // Target backend (zig, c, verilog, rust, etc.)
        emit_comments: bool,           // Include test descriptions as comments
        emit_benchmarks: bool,         // Include benchmark code
        output_format: []const u8,     // Format of output (code, json, xml, etc.)
    };

    // TestGen context
    pub const TestGen = struct {
        ast: Program,
        options: TestGenOptions,
        output: StringBuilder,

        pub fn new(ast_node: Program, opts: TestGenOptions) TestGen {
            return TestGen{
                .ast = ast_node,
                .options = opts,
                .output = StringBuilder.new(65536),
            };
        }

        pub fn generate(self: *TestGen) []const u8 {
            if (std.mem.eql(u8, self.options.backend, "zig")) {
                return self.generate_zig_tests();
            } else if (std.mem.eql(u8, self.options.backend, "c")) {
                return self.generate_c_tests();
            } else if (std.mem.eql(u8, self.options.backend, "verilog")) {
                return self.generate_verilog_tests();
            } else if (std.mem.eql(u8, self.options.backend, "rust")) {
                return self.generate_rust_tests();
            } else if (std.mem.eql(u8, self.options.backend, "json")) {
                return self.generate_conformance_json();
            } else {
                return "// Unsupported backend: " ++ self.options.backend;
            }
        }

        // Generate Zig tests
        pub fn generate_zig_tests(self: *TestGen) []const u8 {
            self.emit("// Zig tests generated from ");
            self.emit(self.ast.source_file);
            self.emit_line("");
            self.emit("const std = @import(\"std\");");
            self.emit_line("");
            self.emit_line("// ===============================================================");
            self.emit_line("// TDD-Inside-Spec: Generated Tests");
            self.emit_line("// ===============================================================");
            self.emit_line("");

            // Generate from spec_decl (high-level TDD)
            if (self.ast.spec_decl) |spec_decl| {
                self.generate_spec_tests_zig(spec_decl);
            }

            // Generate from test_section (assembly-style)
            if (self.ast.test_section) |test_section| {
                self.generate_assembly_tests_zig(test_section);
            }

            // Generate invariants
            if (self.ast.invariant_section) |inv_section| {
                self.generate_invariants_zig(inv_section);
            }

            // Generate benchmarks
            if (self.ast.bench_section) |bench_section| and self.options.emit_benchmarks {
                self.generate_benchmarks_zig(bench_section);
            }

            return self.output.to_string();
        }

        // Generate C tests
        pub fn generate_c_tests(self: *TestGen) []const u8 {
            self.emit("// C tests generated from ");
            self.emit(self.ast.source_file);
            self.emit_line("");
            self.emit("#include <assert.h>");
            self.emit_line("");
            self.emit_line("// ===============================================================");
            self.emit_line("// TDD-Inside-Spec: Generated Tests");
            self.emit_line("// ===============================================================");
            self.emit_line("");

            // Generate from spec_decl
            if (self.ast.spec_decl) |spec_decl| {
                self.generate_spec_tests_c(spec_decl);
            }

            // Generate from test_section
            if (self.ast.test_section) |test_section| {
                self.generate_assembly_tests_c(test_section);
            }

            return self.output.to_string();
        }

        // Generate Verilog testbench
        pub fn generate_verilog_tests(self: *TestGen) []const u8 {
            self.emit("// Verilog testbench generated from ");
            self.emit(self.ast.source_file);
            self.emit_line("");
            self.emit_line("// ===============================================================");
            self.emit_line("// TDD-Inside-Spec: Generated Testbench");
            self.emit_line("// ===============================================================");
            self.emit_line("");

            self.emit("`timescale 1ns/1ps");
            self.emit_line("");
            self.emit("module tb_");
            self.emit(self.mangle_filename(self.ast.source_file));
            self.emit("();");
            self.emit_line("");
            self.emit_line("  // Testbench: clock, reset, stimulus generation, response checking");
            self.emit_line("  // Clock: 100MHz (10ns period)");
            self.emit_line("  // Reset: active-low, 100ns duration");
            self.emit_line("  // Stimulus: based on test_cases in test_section");
            self.emit_line("  // Response: verify against expected_outcome");
            self.emit_line("");
            self.emit_line("  // TODO: Parse test_section.test_cases and generate:");
            self.emit_line("  //   - Clock generator with 50% duty cycle");
            self.emit_line("  //   - Reset sequence (async reset, release after 10 cycles)");
            self.emit_line("  //   - Apply test input vectors");
            self.emit_line("  //   - Monitor output and assert expected values");
            self.emit_line("  //   - Report pass/fail status");
            self.emit_line("");
            self.emit_line("  // Signal declarations:");
            self.emit_line("  //   reg clk, rst_n;");
            self.emit_line("  //   wire [DATA_WIDTH-1:0] data_out;");
            self.emit_line("");
            self.emit_line("  // DUT instantiation:");
            self.emit_line("  //   module_name dut (.clk(clk), .rst_n(rst_n), ...);");
            self.emit_line("");
            self.emit("endmodule");

            return self.output.to_string();
        }

        // Generate Rust tests
        pub fn generate_rust_tests(self: *TestGen) []const u8 {
            self.emit("// Rust tests generated from ");
            self.emit(self.ast.source_file);
            self.emit_line("");
            self.emit_line("#[cfg(test)]");
            self.emit("mod tests {");
            self.emit_line("");
            self.emit_line("    use super::*;");
            self.emit_line("");
            self.emit_line("    // ===============================================================");
            self.emit_line("    // TDD-Inside-Spec: Generated Tests");
            self.emit_line("    // ===============================================================");
            self.emit_line("");

            // Generate from spec_decl
            if (self.ast.spec_decl) |spec_decl| {
                self.generate_spec_tests_rust(spec_decl);
            }

            // Generate from test_section
            if (self.ast.test_section) |test_section| {
                self.generate_assembly_tests_rust(test_section);
            }

            self.emit_line("}");

            return self.output.to_string();
        }

        // Generate conformance JSON
        pub fn generate_conformance_json(self: *TestGen) []const u8 {
            var json: []const u8 = "{\n";
            json = json ++ "  \"spec\": \"" ++ self.ast.source_file ++ "\",\n";
            json = json ++ "  \"generated_at\": \"[timestamp]\",\n";
            json = json ++ "  \"test_vectors\": [\n";

            // Add from test_section
            if (self.ast.test_section) |test_section| {
                for (test_section.test_cases) |test_case| {
                    json = json ++ "    {\n";
                    json = json ++ "      \"name\": \"" ++ test_case.name ++ "\",\n";
                    json = json ++ "      \"verify\": \"" ++ self.escape_json(test_case.verify_description) ++ "\",\n";
                    json = json ++ "      \"expected\": \"" ++ self.escape_json(test_case.expected_outcome) ++ "\"\n";
                    json = json ++ "    },\n";
                }
            }

            // Add from spec_decl
            if (self.ast.spec_decl) |spec_decl| {
                for (spec_decl.test_blocks) |test_block| {
                    json = json ++ "    {\n";
                    json = json ++ "      \"name\": \"" ++ test_block.name ++ "\",\n";
                    json = json ++ "      \"type\": \"spec_test\"\n";
                    json = json ++ "    },\n";
                }
            }

            // Add invariants
            if (self.ast.spec_decl) |spec_decl| {
                for (spec_decl.invariants) |inv| {
                    json = json ++ "    {\n";
                    json = json ++ "      \"name\": \"invariant_" ++ std.fmt.digitToChar(@intCast(inv.line % 10)) ++ "\",\n";
                    json = json ++ "      \"type\": \"invariant\",\n";
                    json = json ++ "      \"assert\": \"" ++ self.escape_json(inv.expression) ++ "\"\n";
                    json = json ++ "    },\n";
                }
            }

            // Remove trailing comma
            json = json[0..json.len - 2];
            json = json ++ "\n";
            json = json ++ "  ]\n";
            json = json ++ "}\n";

            return json;
        }

        // Generate spec tests for Zig
        fn generate_spec_tests_zig(self: *TestGen, spec: SpecDecl) void {
            for (spec.test_blocks) |test_block| {
                self.emit("test \"");
                self.emit(test_block.name);
                self.emit("\" {");
                self.emit_line("");
                self.emit("    // Given:");
                self.emit_line("");
                for (test_block.given_clauses) |given| {
                    self.emit("    const ");
                    self.emit(given.variable);
                    self.emit(" = ");
                    self.emit(given.expression);
                    self.emit(";");
                    self.emit_line("");
                }
                self.emit("    // When:");
                self.emit_line("");
                for (test_block.when_clauses) |when| {
                    self.emit("    const ");
                    self.emit(when.variable);
                    self.emit(" = ");
                    self.emit(when.expression);
                    self.emit(";");
                    self.emit_line("");
                }
                self.emit("    // Then:");
                self.emit_line("");
                for (test_block.then_clauses) |then| {
                    self.emit("    try std.testing.expect(");
                    self.emit(then.expression);
                    self.emit(");");
                    self.emit_line("");
                }
                self.emit("}");
                self.emit_line("");
            }
        }

        // Generate spec tests for C
        fn generate_spec_tests_c(self: *TestGen, spec: SpecDecl) void {
            for (spec.test_blocks) |test_block| {
                self.emit("void test_");
                self.emit(test_block.name);
                self.emit("(void) {");
                self.emit_line("");
                self.emit("    // Given:");
                self.emit_line("");
                for (test_block.given_clauses) |given| {
                    self.emit("    const ");
                    self.emit(self.c_type_from_expr(given.expression));
                    self.emit(" ");
                    self.emit(given.variable);
                    self.emit(" = ");
                    self.emit(given.expression);
                    self.emit(";");
                    self.emit_line("");
                }
                self.emit("    // When:");
                self.emit_line("");
                for (test_block.when_clauses) |when| {
                    self.emit("    const ");
                    self.emit(self.c_type_from_expr(when.expression));
                    self.emit(" ");
                    self.emit(when.variable);
                    self.emit(" = ");
                    self.emit(when.expression);
                    self.emit(";");
                    self.emit_line("");
                }
                self.emit("    // Then:");
                self.emit_line("");
                for (test_block.then_clauses) |then| {
                    self.emit("    assert(");
                    self.emit(then.expression);
                    self.emit(");");
                    self.emit_line("");
                }
                self.emit("}");
                self.emit_line("");
            }
        }

        // Generate spec tests for Rust
        fn generate_spec_tests_rust(self: *TestGen, spec: SpecDecl) void {
            for (spec.test_blocks) |test_block| {
                self.emit("    #[test]");
                self.emit_line("");
                self.emit("    fn test_");
                self.emit(self.to_snake_case(test_block.name));
                self.emit("() {");
                self.emit_line("");
                self.emit("        // Given:");
                self.emit_line("");
                for (test_block.given_clauses) |given| {
                    self.emit("        let ");
                    self.emit(given.variable);
                    self.emit(" = ");
                    self.emit(given.expression);
                    self.emit(";");
                    self.emit_line("");
                }
                self.emit("        // When:");
                self.emit_line("");
                for (test_block.when_clauses) |when| {
                    self.emit("        let ");
                    self.emit(when.variable);
                    self.emit(" = ");
                    self.emit(when.expression);
                    self.emit(";");
                    self.emit_line("");
                }
                self.emit("        // Then:");
                self.emit_line("");
                for (test_block.then_clauses) |then| {
                    self.emit("        assert!(");
                    self.emit(then.expression);
                    self.emit(");");
                    self.emit_line("");
                }
                self.emit("    }");
                self.emit_line("");
            }
        }

        // Generate assembly-style tests for Zig
        fn generate_assembly_tests_zig(self: *TestGen, test_section: TestSection) void {
            for (test_section.test_cases) |test_case| {
                self.emit("test \"");
                self.emit(test_case.name);
                self.emit("\" {");
                self.emit_line("");
                self.emit("    // Verify: ");
                self.emit_line(test_case.verify_description);
                self.emit("    // Expected: ");
                self.emit_line(test_case.expected_outcome);
                self.emit_line("    // TODO: Parse verify_description and generate Zig test code:");
                self.emit_line("    //   1. Parse for function call pattern (e.g., \"my_func(42) returns 42\")");
                self.emit_line("    //   2. Parse expected_outcome for assertion value");
                self.emit_line("    //   3. Generate: const actual = <function_call>;");
                self.emit_line("    //   4. Generate: try std.testing.expectEqual(expected, actual);");
                self.emit_line("");
                self.emit_line("    // Example patterns:");
                self.emit_line("    //   - Function result: const result = add(@as(i32, 2), @as(i32, 3));");
                self.emit_line("    //     try std.testing.expectEqual(@as(i32, 5), result);");
                self.emit_line("    //   - Property check: try std.testing.expect(value > 0);");
                self.emit_line("    //   - Error handling: try std.testing.expectError(error.Invalid, func());");
                self.emit("    try std.testing.expect(true);  // Placeholder during bootstrap");
                self.emit_line("");
                self.emit("}");
                self.emit_line("");
            }
        }

        // Generate assembly-style tests for C
        fn generate_assembly_tests_c(self: *TestGen, test_section: TestSection) void {
            for (test_section.test_cases) |test_case| {
                self.emit("void test_");
                self.emit(test_case.name);
                self.emit("(void) {");
                self.emit_line("");
                self.emit("    // Verify: ");
                self.emit_line(test_case.verify_description);
                self.emit("    // Expected: ");
                self.emit_line(test_case.expected_outcome);
                self.emit_line("    // TODO: Parse verify_description and generate C test code:");
                self.emit_line("    //   1. Parse for function call pattern");
                self.emit_line("    //   2. Parse expected_outcome for assertion value");
                self.emit_line("    //   3. Generate: type actual = <function_call>;");
