        // Generate invariants as Zig tests
        fn generate_invariants_zig(self: *TestGen, inv_section: InvariantSection) void {
            for (inv_section.invariants) |inv| {
                self.emit("test \"invariant_");
                self.emit(inv.name);
                self.emit("\" {");
                self.emit_line("");
                self.emit("    // Invariant: ");
                self.emit_line(inv.formal_statement);
                self.emit("    // Rationale: ");
                self.emit_line(inv.rationale);
                self.emit_line("    // TODO: Parse formal_statement and generate Zig invariant assertion:");
                self.emit_line("    //   1. Parse for invariant type (bounds, equality, property)");
                self.emit_line("    //   2. Parse for subject (variable, function call, state)");
                self.emit_line("    //   3. Generate appropriate Zig assertion");
                self.emit_line("");
                self.emit_line("    // Invariant patterns:");
                self.emit_line("    //   - Bounds: try std.testing.expect(value >= min and value <= max);");
                self.emit_line("    //   - Equality: try std.testing.expect(actual == expected);");
                self.emit_line("    //   - Emptiness: try std.testing.expect(count == 0);");
                self.emit_line("    //   - Non-null: try std.testing.expect(ptr != null);");
                self.emit_line("    //   - Always-true identity: try std.testing.expect(true);");
                self.emit("    try std.testing.expect(true);  // Placeholder during bootstrap");
                self.emit_line("");
                self.emit("}");
                self.emit_line("");
            }
        }

        // Generate benchmarks as Zig tests
        fn generate_benchmarks_zig(self: *TestGen, bench_section: BenchSection) void {
            for (bench_section.benchmarks) |bench| {
                self.emit("test \"bench_");
                self.emit(bench.name);
                self.emit("\" {");
                self.emit_line("");
                self.emit("    // Measure: ");
                self.emit_line(bench.measure_description);
                if (bench.target != null) {
                    self.emit("    // Target: ");
                    self.emit_line(bench.target.?);
                }
                self.emit("    // Units: ");
                self.emit_line(bench.units);
                self.emit("    const timer = try std.time.Timer.start();");
                self.emit("    _ = timer;");
                self.emit_line("");
                self.emit("}");
                self.emit_line("");
            }
        }

        // Mangle filename to valid identifier
        fn mangle_filename(self: *TestGen, filename: []const u8) []const u8 {
            var result: []const u8 = "";
            var start: usize = filename.len - 1;

            // Find last path separator
            while (start >= 0 and filename[start] != '/' and filename[start] != '\\') {
                if (start == 0) break;
                start -= 1;
            }

            // Extract filename without extension
            var i: usize = start + 1;
            while (i < filename.len) : (i += 1) {
                const c = filename[i];
                if (c == '.') break;
                if ((c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or (c >= '0' and c <= '9') or c == '_') {
                    result = result ++ [_]u8{c};
                } else {
                    result = result ++ "_";
                }
            }

            return result;
        }

        // Escape JSON string
        fn escape_json(self: *TestGen, s: []const u8) []const u8 {
            var result: []const u8 = "";
            var i: usize = 0;
            while (i < s.len) : (i += 1) {
                const c = s[i];
                if (c == '"') {
                    result = result ++ "\\\"";
                } else if (c == '\\') {
                    result = result ++ "\\\\";
                } else if (c == '\n') {
                    result = result ++ "\\n";
                } else if (c == '\r') {
                    result = result ++ "\\r";
                } else if (c == '\t') {
                    result = result ++ "\\t";
                } else {
                    result = result ++ [_]u8{c};
                }
            }
            return result;
        }

        // Convert to snake_case
        fn to_snake_case(self: *TestGen, s: []const u8) []const u8 {
            var result: []const u8 = "";
            var i: usize = 0;
            while (i < s.len) : (i += 1) {
                const c = s[i];
                if (c >= 'A' and c <= 'Z') {
                    if (result.len > 0) {
                        result = result ++ "_";
                    }
                    result = result ++ [_]u8{c + 32}; // to lower case
                } else if ((c >= 'a' and c <= 'z') or (c >= '0' and c <= '9') or c == '_') {
                    result = result ++ [_]u8{c};
                } else {
                    if (result.len > 0) {
                        result = result ++ "_";
                    }
                }
            }
            return result;
        }

        // Infer C type from expression
        fn c_type_from_expr(self: *TestGen, expr: []const u8) []const u8 {
            // Simple heuristic - look for float literals
            var i: usize = 0;
            while (i < expr.len) : (i += 1) {
                const c = expr[i];
                if (c == '.' or c == 'e' or c == 'E') {
                    return "double";
                }
            }
            return "int";
        }

        // Emit helpers
        fn emit(self: *TestGen, s: []const u8) void {
            self.output.append(s);
        }

        fn emit_line(self: *TestGen, s: []const u8) void {
            self.output.append(s);
            self.output.append("\n");
        }
    };

    // StringBuilder
    pub const StringBuilder = struct {
        buffer: []u8,
        len: u32,
        capacity: u32,

        pub fn new(capacity: u32) StringBuilder {
            return StringBuilder{
                .buffer = [_]u8{0} ** capacity,
                .len = 0,
                .capacity = capacity,
            };
        }

        pub fn append(self: *StringBuilder, s: []const u8) void {
            var i: usize = 0;
            while (i < s.len and self.len < self.capacity) : (i += 1) {
                self.buffer[self.len] = s[i];
                self.len += 1;
            }
        }

        pub fn to_string(self: *StringBuilder) []const u8 {
            return self.buffer[0..self.len];
        }
    };

    // Types from AST (simplified for testgen)
    pub const Program = struct {
        source_file: []const u8,
        spec_decl: ?SpecDecl,
        test_section: ?TestSection,
        invariant_section: ?InvariantSection,
        bench_section: ?BenchSection,
    };

    pub const SpecDecl = struct {
        test_blocks: []TestBlock,
        invariants: []Invariant,
    };

    pub const TestSection = struct {
        test_cases: []TestCase,
    };

    pub const InvariantSection = struct {
        invariants: []Invariant,
    };

    pub const BenchSection = struct {
        benchmarks: []Benchmark,
    };

    pub const TestBlock = struct {
        name: []const u8,
        given_clauses: []Clause,
        when_clauses: []Clause,
        then_clauses: []Clause,
    };

    pub const TestCase = struct {
        name: []const u8,
        verify_description: []const u8,
        expected_outcome: []const u8,
    };

    pub const Invariant = struct {
        name: []const u8,
        formal_statement: []const u8,
        rationale: []const u8,
        expression: []const u8,
        line: u32,
    };

    pub const Benchmark = struct {
        name: []const u8,
        measure_description: []const u8,
        target: ?[]const u8,
        units: []const u8,
    };

    pub const Clause = struct {
        variable: []const u8,
        expression: []const u8,
    };
}

