// SPDX-License-Identifier: Apache-2.0
// t27/specs/isa/registers.t27
// TRI27 ISA Register File Specification
// Register definitions, Coptic encoding, and register file operations
// phi^2 + 1/phi^2 = 3 | TRINITY

module ISARegisters {
    // Import base types
    use base::types;

    // =================================================================
    // 1. Register Constants
    // =========================================================================

    // Register file configuration (Coptic compatibility: 27 registers)
    const NUM_REGISTERS : usize = 27;   // R0-R26
    const REG_WIDTH : usize = 27;       // Each register holds 27 trits (TernaryWord)
    const COPIC_BASE : usize = 27;      // Coptic numerals base

    // Agent-register binding (Ring 045)
    const AGENT_COUNT : usize = 27;     // 27 agents map to 27 registers

    // Register identifiers
    const R0 : u8 = 0;   // Zero register (always reads as 0)
    const R1 : u8 = 1;   // Argument/return register
    const R2 : u8 = 2;   // Argument/return register
    const R3 : u8 = 3;   // Argument register
    const R4 : u8 = 4;   // Argument register
    const R5 : u8 = 5;   // Temporary register
    const R6 : u8 = 6;   // Temporary register
    const R7 : u8 = 7;   // Temporary register
    const R8 : u8 = 8;   // Temporary register
    const R9 : u8 = 9;   // Temporary register
    const R10 : u8 = 10; // Saved register S0
    const R11 : u8 = 11; // Saved register S1
    const R12 : u8 = 12; // Saved register S2
    const R13 : u8 = 13; // Saved register S3
    const R14 : u8 = 14; // Saved register S4
    const R15 : u8 = 15; // Saved register S5
    const R16 : u8 = 16; // Frame pointer
    const R17 : u8 = 17; // Stack pointer
    const R18 : u8 = 18; // Link register
    const R19 : u8 = 19; // Program counter
    const R20 : u8 = 20; // Status register
    const R21 : u8 = 21; // Exception handler
    const R22 : u8 = 22; // Kernel stack pointer
    const R23 : u8 = 23; // Thread pointer
    const R24 : u8 = 24; // Reserved for architecture
    const R25 : u8 = 25; // Reserved for architecture
    const R26 : u8 = 26; // Reserved for architecture

    // Status register flags (R20)
    const FLAG_ZERO : u8 = 0;      // Zero flag
    const FLAG_NEG : u8 = 1;       // Negative flag
    const FLAG_CARRY : u8 = 2;     // Carry flag
    const FLAG_OVERFLOW : u8 = 3;  // Overflow flag
    const FLAG_TRAP : u8 = 4;      // Trap flag
    const FLAG_INTERRUPT : u8 = 5; // Interrupt enable

    // =================================================================
    // 2. Coptic Alphabet Encoding
    // =========================================================================

    // Coptic alphabet encoding (27 letters for 27 registers)
    // Maps register numbers to Coptic Unicode code points
    const COPTIC_ALPHABET : [27]u32 = [
        0x03B1,  // alpha = alpha (R0)
        0x03B2,  // beta = bita (R1)
        0x03B3,  // gamma = gamma (R2)
        0x03B4,  // delta = dalda (R3)
        0x03B5,  // epsilon = ei (R4)
        0x03C6,  // phi = sima (R5)
        0x03B6,  // zeta = zata (R6)
        0x03B7,  // eta = ita (R7)
        0x03B8,  // theta = thita (R8)
        0x03B9,  // iota = iota (R9)
        0x03BA,  // kappa = kappa (R10)
        0x03BB,  // lambda = lauda (R11)
        0x03BC,  // mu = mi (R12)
        0x03BD,  // nu = ni (R13)
        0x03BE,  // xi = ksi (R14)
        0x03C0,  // pi = pi (R15)
        0x03C1,  // rho = ro (R16)
        0x03C3,  // sigma = sigma (R17)
        0x03C4,  // tau = tau (R18)
        0x03C5,  // upsilon = upsilon (R19)
        0x03C6,  // phi = fi (R20)
        0x03C7,  // chi = khi (R21)
        0x03C8,  // psi = psi (R22)
        0x03C9,  // omega = ou (R23)
        0x0417,  // 304 = sampi (R24)
        0x0418,  // 305 = koppa (R25)
        0x0419,  // 306 = 307hei (R26)
    ];

    // =================================================================
    // 3. Register File State
    // =========================================================================

    // Register file: 27 registers, each holding a TernaryWord (27 trits)
    // Stored as u32 for efficiency (27 trits fits in 32 bits)
    var register_file : [NUM_REGISTERS]TernaryWord = [TernaryWord{.raw = 0}; NUM_REGISTERS];

    // =================================================================
    // 4. Register Read/Write
    // =========================================================================

    // reg_read(reg: u8) -> TernaryWord
    // Read from register file
    // R0 always returns 0 (zero register)
    // Returns error sentinel if register number is invalid
    fn reg_read(reg: u8) -> TernaryWord {
        // Check for R0 (zero register)
        if (reg == R0) {
            return TernaryWord{ .raw = 0 };
        }

        // Validate register number
        if (reg > R26) {
            // Invalid register - trap or return error
            return TernaryWord{ .raw = 0 };  // Error case
        }

        return register_file[reg];
    }

    // reg_write(reg: u8, value: TernaryWord) -> bool
    // Write to register file
    // R0 writes are ignored (zero register is read-only)
    // Returns true if write succeeded, false if invalid register
    fn reg_write(reg: u8, value: TernaryWord) -> bool {
        // Check for R0 (zero register - ignore writes)
        if (reg == R0) {
            return false;
        }

        // Validate register number
        if (reg > R26) {
            return false;
        }

        register_file[reg] = value;
        return true;
    }

    // =================================================================
    // 5. Coptic Encoding Conversion
    // =========================================================================

    // reg_to_coptic(reg: u8) -> u32
    // Convert register number to Coptic Unicode code point
    // Returns 0 if register number is invalid
    fn reg_to_coptic(reg: u8) -> u32 {
        if (reg > R26) {
            return 0;
        }
        return COPTIC_ALPHABET[reg];
    }

    // coptic_to_reg(cp: u32) -> u8
    // Convert Coptic Unicode code point to register number
    // Returns 0xFF if not a valid register character
    fn coptic_to_reg(cp: u32) -> u8 {
        var i : u8 = 0;

        while (i < 27) {
            if (COPTIC_ALPHABET[i] == cp) {
                return i;
            }
            i = i + 1;
        }

        return 0xFF;  // Error sentinel
    }

    // =================================================================
    // 6. Status Register Operations
    // =========================================================================

    // status_read(flag: u8) -> bool
    // Read a specific flag from status register (R20)
    // Returns true if flag is set, false otherwise
    fn status_read(flag: u8) -> bool {
        const status_val = reg_read(R20);
        const mask = 1u32 << flag;
        return (status_val.raw & mask) != 0;
    }

    // status_write(flag: u8, value: bool) -> bool
    // Set or clear a specific flag in status register (R20)
    // Returns true if operation succeeded
    fn status_write(flag: u8, value: bool) -> bool {
        if (flag > 5) {
            return false;
        }

        var status_val = reg_read(R20);
        const mask = 1u32 << flag;

        if (value) {
            status_val.raw = status_val.raw | mask;
        } else {
            status_val.raw = status_val.raw & ~mask;
        }

        return reg_write(R20, status_val);
    }

    // =================================================================
    // 7. Stack Operations (using R17 as stack pointer)
    // =========================================================================

    // push_reg(reg: u8) -> bool
    // Push register value to stack (using R17 as stack pointer)
    // Stack grows downward (decrement before store)
    // Returns true if push succeeded
    fn push_reg(reg: u8) -> bool {
        // Read register value
        const value = reg_read(reg);

        // Get stack pointer (R17)
        var sp = reg_read(R17);

        // Decrement SP (each stack entry is 4 bytes)
        sp.raw = sp.raw - 4;

        // Write back SP
        if (!reg_write(R17, sp)) {
            return false;
        }

        // Store value to [SP]
        // (In real implementation, would write to memory at address SP)
        // For spec, we simulate with a separate stack buffer
        // ...

        return true;
    }

    // pop_reg(reg: u8) -> bool
    // Pop value from stack into register (using R17 as stack pointer)
    // Stack grows downward (load then increment)
    // Returns true if pop succeeded
    fn pop_reg(reg: u8) -> bool {
        // Get stack pointer (R17)
        var sp = reg_read(R17);

        // Load value from [SP]
        // (In real implementation, would read from memory at address SP)
        const value = TernaryWord{ .raw = 0 };  // Placeholder

        // Increment SP
        sp.raw = sp.raw + 4;

        // Write back SP
        if (!reg_write(R17, sp)) {
            return false;
        }

        // Write value to register
        return reg_write(reg, value);
    }

    // =================================================================
    // 8. Context Save/Restore
    // =========================================================================

    // save_context() -> void
    // Save caller-saved registers (R5-R9) to stack
    // Used by function prologue
    fn save_context() -> void {
        push_reg(R5);
        push_reg(R6);
        push_reg(R7);
        push_reg(R8);
        push_reg(R9);
    }

    // restore_context() -> void
    // Restore caller-saved registers from stack
    // Used by function epilogue
    fn restore_context() -> void {
        pop_reg(R9);
        pop_reg(R8);
        pop_reg(R7);
        pop_reg(R6);
        pop_reg(R5);
    }

    // =================================================================
    // 9. Register Aliases
    // =========================================================================

    // Argument/return registers
    const ARG0 : u8 = R1;
    const ARG1 : u8 = R2;
    const ARG2 : u8 = R3;
    const ARG3 : u8 = R4;

    // Temporary registers (caller-saved)
    const TMP0 : u8 = R5;
    const TMP1 : u8 = R6;
    const TMP2 : u8 = R7;
    const TMP3 : u8 = R8;
    const TMP4 : u8 = R9;

    // Saved registers (callee-saved)
    const SAVED0 : u8 = R10;
    const SAVED1 : u8 = R11;
    const SAVED2 : u8 = R12;
    const SAVED3 : u8 = R13;
    const SAVED4 : u8 = R14;
    const SAVED5 : u8 = R15;

    // Special purpose registers
    const FP : u8 = R16;   // Frame pointer
    const SP : u8 = R17;   // Stack pointer
    const LR : u8 = R18;   // Link register
    const PC : u8 = R19;   // Program counter
    const STATUS : u8 = R20;  // Status register
    const EH : u8 = R21;   // Exception handler
    const KSP : u8 = R22;  // Kernel stack pointer
    const TP : u8 = R23;   // Thread pointer

    // =======================================================================================================
    // TDD-Inside-Spec: Tests and Invariants for ISARegisters
    // =======================================================================================================

    test isa_r0_always_zero
        given word = TernaryWord{.raw = 0x123456}
        and   reg_write(R0, word)
        and   result = reg_read(R0)
        then result.raw == 0

    test isa_r0_write_ignored
        given before = reg_read(R0)
        and   success = reg_write(R0, TernaryWord{.raw = 0xDEADBEEF})
        and   after = reg_read(R0)
        then success == false and before.raw == after.raw and after.raw == 0

    test isa_register_count_27
        given count = NUM_REGISTERS
        then count == 27

    test isa_valid_register_write_succeeds
        given value = TernaryWord{.raw = 0xABCDEF}
        and   success = reg_write(R10, value)
        then success == true

    test isa_valid_register_write_read_roundtrip
        given value = TernaryWord{.raw = 0x123456}
        and   reg_write(R10, value)
        and   result = reg_read(R10)
        then result.raw == value.raw

    test isa_invalid_register_write_fails
        given value = TernaryWord{.raw = 0x123456}
        and   success = reg_write(27, value)  // R27 doesn't exist
        then success == false

    test isa_invalid_register_read_returns_zero
        given result = reg_read(27)
        then result.raw == 0

    test isa_reg_to_coptic_r0
        given cp = reg_to_coptic(R0)
        then cp == 0x03B1  // alpha

    test isa_reg_to_coptic_r10
        given cp = reg_to_coptic(R10)
        then cp == 0x03BA  // kappa

    test isa_reg_to_coptic_r26
        given cp = reg_to_coptic(R26)
        then cp == 0x0419  // 1492

    test isa_coptic_to_reg_alpha
        given reg = coptic_to_reg(0x03B1)  // alpha
        then reg == R0

    test isa_coptic_to_reg_kappa
        given reg = coptic_to_reg(0x03BA)  // kappa
        then reg == R10

    test isa_coptic_to_reg_invalid
        given reg = coptic_to_reg(0x0041)  // 'A' - not Coptic
        then reg == 0xFF

    test isa_coptic_roundtrip_r0
        given original_cp = reg_to_coptic(R0)
        and   recovered_reg = coptic_to_reg(original_cp)
        and   recovered_cp = reg_to_coptic(recovered_reg)
        then original_cp == recovered_cp

    test isa_coptic_roundtrip_r15
        given original_cp = reg_to_coptic(R15)
        and   recovered_reg = coptic_to_reg(original_cp)
        and   recovered_cp = reg_to_coptic(recovered_reg)
        then original_cp == recovered_cp

    test isa_status_read_initial_false
        given flag_val = status_read(FLAG_ZERO)
        then flag_val == false

    test isa_status_write_set
        given status_write(FLAG_ZERO, true)
        and   flag_val = status_read(FLAG_ZERO)
        then flag_val == true

    test isa_status_write_clear
        given status_write(FLAG_ZERO, true)
        and   status_write(FLAG_ZERO, false)
        and   flag_val = status_read(FLAG_ZERO)
        then flag_val == false

    test isa_status_flags_independent
        given status_write(FLAG_ZERO, true)
        and   status_write(FLAG_NEG, true)
        and   zero_val = status_read(FLAG_ZERO)
        and   neg_val = status_read(FLAG_NEG)
        then zero_val == true and neg_val == true

    test isa_status_invalid_flag
        given success = status_write(10, true)  // Invalid flag
        then success == false

    test isa_register_aliases_match
        given arg0 = ARG0 and arg1 = ARG1 and sp = SP and fp = FP
        then arg0 == R1 and arg1 == R2 and sp == R17 and fp == R16

    test isa_coptic_alphabet_size_27
        given size = COPTIC_ALPHABET.len()
        then size == 27

    invariant isa_num_registers_constant
        assert NUM_REGISTERS == 27

    invariant isa_reg_width_is_27
        assert REG_WIDTH == 27

    invariant isa_coptic_base_constant
        assert COPIC_BASE == 27

    invariant isa_coptic_alphabet_size_matches_registers
        assert COPTIC_ALPHABET.len() == NUM_REGISTERS

    invariant isa_r0_readonly_zero
        given val = reg_read(R0)
        assert val.raw == 0

    invariant isa_r0_write_no_op
        given original = reg_read(R0)
        and   reg_write(R0, TernaryWord{.raw = 0xFFFFFFFF})
        and   after = reg_read(R0)
        assert original.raw == after.raw and after.raw == 0

    invariant isa_coptic_to_reg_is_inverse_of_reg_to_coptic
        for (const i) |reg| in [0u8, 5, 10, 15, 20, 26] {
            const cp = reg_to_coptic(reg);
            const recovered = coptic_to_reg(cp);
            assert recovered == reg;
        }

    invariant isa_coptic_alphabet_unique
        given seen = [false; 256]  // Track seen code points
        and   all_unique = true
        and   idx = 0
        while (idx < COPTIC_ALPHABET.len()) {
            const cp = COPTIC_ALPHABET[idx];
            if (cp < 256 and seen[cp]) {
                all_unique = false;
                break;
            }
            if (cp < 256) { seen[cp] = true; }
            idx = idx + 1;
        }
        assert all_unique

    invariant isa_status_flags_in_range
        assert FLAG_ZERO <= 5 and FLAG_INTERRUPT <= 5

    invariant isa_register_aliases_correct
        assert ARG0 == R1 and ARG1 == R2 and ARG2 == R3 and ARG3 == R4
        assert TMP0 == R5 and TMP1 == R6 and TMP2 == R7 and TMP3 == R8 and TMP4 == R9
        assert SAVED0 == R10 and SAVED1 == R11 and SAVED2 == R12 and SAVED3 == R13
        assert FP == R16 and SP == R17 and LR == R18 and PC == R19 and STATUS == R20

    invariant isa_register_indices_valid
        assert R0 == 0 and R10 == 10 and R20 == 20 and R26 == 26

    invariant isa_max_register_is_26
        assert R26 == NUM_REGISTERS - 1

    // =================================================================
    // Ring 045: Agent Binding and Trit State Invariants
    // =========================================================================

    // agent_register_bijection: Each agent maps to exactly one register
    invariant agent_register_bijection
        assert AGENT_COUNT == NUM_REGISTERS
        assert NUM_REGISTERS == 27
        assert COPIC_BASE == 27

    // trit_state: All trit values must be in {-1, 0, +1}
    invariant trit_state
        given r0 = reg_read(R0)
        and   r1 = reg_read(R1)
        and   r10 = reg_read(R10)
        and   r26 = reg_read(R26)
        // All trit values in registers must be valid
        // (verified by TernaryWord type constraints)

    // no_trit_overflow: All register operations produce valid trits
    invariant no_trit_overflow
        // Register read/write operations preserve trit validity
        given value = TernaryWord{.raw = 0x123456}
        and   reg_write(R10, value)
        and   result = reg_read(R10)
        assert result.raw == value.raw

    // queen_register_special: T (Queen) register = register index 0 (Tau/Alpha)
    // The Queen register is R0 (Alpha/alpha), the first Coptic letter
    invariant queen_register_special
        assert R0 == 0
        assert reg_to_coptic(R0) == 0x03B1  // alpha (Alpha, representing Queen/Tau)

    // register_initial_zero: All registers initialize to 0
    invariant register_initial_zero
        given i = 0
        while (i < NUM_REGISTERS) {
            const val = reg_read(i as u8);
            if (i == 0) {
                assert val.raw == 0;  // R0 is always 0
            }
            // Other registers have initial state (managed by register_file)
            i = i + 1;
        }

    // Tests for Ring 045 requirements

    test register_reset
        // All registers initialize to 0
        given r0_val = reg_read(R0)
        and   r1_val = reg_read(R1)
        and   r10_val = reg_read(R10)
        and   r26_val = reg_read(R26)
        then r0_val.raw == 0 and r1_val.raw == 0 and r10_val.raw == 0 and r26_val.raw == 0

    test queen_register_special
        // T (Queen) register = register index 0 (Tau/Alpha)
        given queen_idx = R0
        and   queen_cp = reg_to_coptic(queen_idx)
        then queen_idx == 0 and queen_cp == 0x03B1  // alpha

    test agent_count_equals_register_count
        given agents = AGENT_COUNT
        and   registers = NUM_REGISTERS
        then agents == registers and registers == 27

    test trit_values_valid
        // Verify trit arithmetic doesn't overflow
        given a = TernaryWord{.raw = 0x123}
        and   b = TernaryWord{.raw = 0x456}
        and   reg_write(R10, a)
        and   result = reg_read(R10)
        then result.raw == a.raw

    bench isa_reg_read_latency
        measure: nanoseconds to reg_read(R10)
        target: < 50ns

    bench isa_reg_write_latency
        measure: nanoseconds to reg_write(R10, TernaryWord{.raw = 0x123456})
        target: < 50ns

    bench isa_reg_to_coptic_latency
        measure: nanoseconds to reg_to_coptic(R15)
        target: < 20ns

    bench isa_coptic_to_reg_latency
        measure: nanoseconds to coptic_to_reg(0x03C0)  // pi
        target: < 100ns

    bench isa_status_read_latency
        measure: nanoseconds to status_read(FLAG_ZERO)
        target: < 100ns

    bench isa_status_write_latency
        measure: nanoseconds to status_write(FLAG_ZERO, true)
        target: < 150ns

    bench isa_save_context_latency
        measure: nanoseconds to save_context()
        target: < 500ns

    bench isa_restore_context_latency
        measure: nanoseconds to restore_context()
        target: < 500ns
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/isa/ternary_memory.t27
// Ternary Memory Specification
// Ring 089 - Memory operations for ternary architecture
// Load/store operations with ternary address and data
// phi^2 + 1/phi^2 = 3 | TRINITY

module ISAMemoryOps {
    use base::types;

    // =================================================================
    // 1. Memory Constants
    // =========================================================================

    // Trit values for memory operations
    const TRIT_NEG : i32 = -1;
    const TRIT_ZERO : i32 = 0;
    const TRIT_POS : i32 = 1;

    // Memory configuration
    const MEM_ADDR_WIDTH : usize = 27;     // 27-trit addresses
    const MEM_DATA_WIDTH : usize = 27;     // 27-trit data words
    const MEM_SIZE : usize = 27;            // 3^27 locations (abstract)
    const WORD_SIZE : usize = 27;           // 27 trits per word

    // Memory alignment
    const ALIGNMENT : usize = 3;            // 3-trit alignment (trit boundary)

    // Access permissions
    const PERM_READ : u8 = 0x1;            // Read permission
    const PERM_WRITE : u8 = 0x2;           // Write permission
    const PERM_EXEC : u8 = 0x4;            // Execute permission

    // =================================================================
    // 2. Memory Operations
    // =========================================================================

    // mem_load(memory: []TernaryWord, addr: u32) -> TernaryWord
    // Load word from memory at address
    // Returns zero word if address is invalid
    fn mem_load(memory: []TernaryWord, addr: u32) -> TernaryWord {
        // Check address bounds
        if (addr >= MEM_SIZE) {
            return TernaryWord{ .raw = 0 };
        }

        return memory[addr];
    }

    // mem_store(memory: []TernaryWord, addr: u32, value: TernaryWord) -> bool
    // Store word to memory at address
    // Returns true if store succeeded
    fn mem_store(memory: []TernaryWord, addr: u32, value: TernaryWord) -> bool {
        // Check address bounds
        if (addr >= MEM_SIZE) {
            return false;
        }

        memory[addr] = value;
        return true;
    }

    // mem_load_aligned(memory: []TernaryWord, addr: u32, align: usize) -> TernaryWord
    // Load with alignment check
    // Returns zero word if alignment fails
    fn mem_load_aligned(memory: []TernaryWord, addr: u32, align: usize) -> TernaryWord {
        // Check alignment
        if (addr % align != 0) {
            return TernaryWord{ .raw = 0 };
        }

        return mem_load(memory, addr);
    }

    // mem_store_aligned(memory: []TernaryWord, addr: u32, value: TernaryWord, align: usize) -> bool
    // Store with alignment check
    // Returns true if store succeeded
    fn mem_store_aligned(memory: []TernaryWord, addr: u32, value: TernaryWord, align: usize) -> bool {
        // Check alignment
        if (addr % align != 0) {
            return false;
        }

        return mem_store(memory, addr, value);
    }

    // =================================================================
    // 3. Block Memory Operations
    // =========================================================================

    // mem_load_block(memory: []TernaryWord, base_addr: u32, count: usize, dest: []TernaryWord) -> bool
    // Load block of memory (count words) from base_addr
    // Used for block load instructions
    fn mem_load_block(memory: []TernaryWord, base_addr: u32, count: usize, dest: []TernaryWord) -> bool {
        // Check bounds
        if (base_addr + count > MEM_SIZE) {
            return false;
        }

        if (base_addr + count > dest.len()) {
            return false;
        }

        // Load each word
        var i : usize = 0;
        while (i < count) {
            dest[i] = memory[base_addr + i];
            i = i + 1;
        }

        return true;
    }

    // mem_store_block(memory: []TernaryWord, base_addr: u32, count: usize, src: []TernaryWord) -> bool
    // Store block of memory (count words) to base_addr
    // Used for block store instructions
    fn mem_store_block(memory: []TernaryWord, base_addr: u32, count: usize, src: []TernaryWord) -> bool {
        // Check bounds
        if (base_addr + count > MEM_SIZE) {
            return false;
        }

        if (base_addr + count > src.len()) {
            return false;
        }

        // Store each word
        var i : usize = 0;
        while (i < count) {
            memory[base_addr + i] = src[i];
            i = i + 1;
        }

        return true;
    }

    // =================================================================
    // 4. Stack Operations (Memory-based)
    // =========================================================================

    // Stack grows downward from high memory
    const STACK_BASE : u32 = MEM_SIZE - 1;

    // mem_push(memory: []TernaryWord, sp: *u32, value: TernaryWord) -> bool
    // Push value to stack (decrement SP, then store)
    fn mem_push(memory: []TernaryWord, sp: *u32, value: TernaryWord) -> bool {
        // Decrement stack pointer
        if (sp.* == 0) {
            return false;  // Stack overflow
        }

        sp.* = sp.* - 1;

        // Store value
        return mem_store(memory, sp.*, value);
    }

    // mem_pop(memory: []TernaryWord, sp: *u32) -> TernaryWord
    // Pop value from stack (load, then increment SP)
    fn mem_pop(memory: []TernaryWord, sp: *u32) -> TernaryWord {
        // Load value
        const value = mem_load(memory, sp.*);

        // Increment stack pointer
        if (sp.* < MEM_SIZE - 1) {
            sp.* = sp.* + 1;
        }

        return value;
    }

    // =================================================================
    // 5. Address Translation (Basic)
    // =========================================================================

    // virt_to_phys(virt_addr: u32, base: u32, limit: u32) -> u32
    // Simple virtual-to-physical address translation
    // Used for segmented memory model
    fn virt_to_phys(virt_addr: u32, base: u32, limit: u32) -> u32 {
        // Check if virtual address is within segment limit
        if (virt_addr > limit) {
            return 0xFFFFFFFF;  // Invalid address
        }

        // Physical = base + virtual
        const phys_addr = base + virt_addr;

        // Check physical bounds
        if (phys_addr >= MEM_SIZE) {
            return 0xFFFFFFFF;
        }

        return phys_addr;
    }

    // =================================================================
    // 6. Memory Protection
    // =========================================================================

    // mem_check_perm(addr: u32, perm: u8, protection_table: []u8) -> bool
    // Check if address has required permission
    fn mem_check_perm(addr: u32, perm: u8, protection_table: []u8) -> bool {
        if (addr >= protection_table.len()) {
            return false;
        }

        return (protection_table[addr] & perm) != 0;
    }

    // mem_protect(memory: []TernaryWord, addr: u32, perm: u8, protection_table: []u8) -> bool
    // Set protection bits for address
    fn mem_protect(memory: []TernaryWord, addr: u32, perm: u8, protection_table: []u8) -> bool {
        if (addr >= protection_table.len()) {
            return false;
        }

        protection_table[addr] = protection_table[addr] | perm;
        return true;
    }

    // =================================================================
    // 7. Memory Copy Operations
    // =========================================================================

    // mem_copy(dst: []TernaryWord, dst_addr: u32, src: []TernaryWord, src_addr: u32, count: usize) -> bool
    // Copy count words from source to destination
    fn mem_copy(dst: []TernaryWord, dst_addr: u32, src: []TernaryWord, src_addr: u32, count: usize) -> bool {
        // Check bounds
        if (dst_addr + count > dst.len() or src_addr + count > src.len()) {
            return false;
        }

        // Handle overlap (copy direction matters)
        if (dst_addr < src_addr) {
            // Copy forward
            var i : usize = 0;
            while (i < count) {
                dst[dst_addr + i] = src[src_addr + i];
                i = i + 1;
            }
        } else {
            // Copy backward
            var i : usize = count;
            while (i > 0) {
                i = i - 1;
                dst[dst_addr + i] = src[src_addr + i];
            }
        }

        return true;
    }

    // mem_fill(dst: []TernaryWord, addr: u32, value: TernaryWord, count: usize) -> bool
    // Fill count words with value
    fn mem_fill(dst: []TernaryWord, addr: u32, value: TernaryWord, count: usize) -> bool {
        // Check bounds
        if (addr + count > dst.len()) {
            return false;
        }

        var i : usize = 0;
        while (i < count) {
            dst[addr + i] = value;
            i = i + 1;
        }

        return true;
    }

    // =================================================================
    // 8. Word Operations
    // =========================================================================

    // word_extract_trit(word: TernaryWord, trit_index: usize) -> i32
    // Extract single trit from word (0 = least significant)
    fn word_extract_trit(word: TernaryWord, trit_index: usize) -> i32 {
        if (trit_index >= WORD_SIZE) {
            return TRIT_ZERO;
        }

        // Extract 2 bits and decode to trit
        const encoded = (word.raw >> (trit_index * 2)) & 0x3;

        if (encoded == 0x0) {
            return TRIT_NEG;
        } else if (encoded == 0x1) {
            return TRIT_ZERO;
        } else {
            return TRIT_POS;
        }
    }

    // word_pack_trit(word: TernaryWord, trit_index: usize, value: i32) -> TernaryWord
    // Pack single trit into word
    fn word_pack_trit(word: TernaryWord, trit_index: usize, value: i32) -> TernaryWord {
        if (trit_index >= WORD_SIZE) {
            return word;
        }

        // Encode trit to 2 bits
        const encoded : u32 = if (value == TRIT_NEG) { 0x0 }
                            else if (value == TRIT_ZERO) { 0x1 }
                            else { 0x2 };

        // Clear and set bits
        const mask = ~(0x3u32 << (trit_index * 2));
        var result = word;
        result.raw = (result.raw & mask) | (encoded << (trit_index * 2));

        return result;
    }

    // =================================================================
    // TDD-Inside-Spec: Tests and Invariants
    // =========================================================================

    test mem_load_valid_address
        given memory = []TernaryWord{TernaryWord{.raw = 0}, TernaryWord{.raw = 0x123}}
        and   value = mem_load(memory, 1)
        then value.raw == 0

    test mem_store_valid_address
        given memory = []TernaryWord{TernaryWord{.raw = 0}, TernaryWord{.raw = 0}}
        and   word = TernaryWord{.raw = 0xABC}
        and   success = mem_store(memory, 1, word)
        and   result = mem_load(memory, 1)
        then success == true and result.raw == 0xABC

    test mem_load_invalid_address
        given memory = []TernaryWord{TernaryWord{.raw = 0}}
        and   value = mem_load(memory, 999)
        then value.raw == 0

    test mem_store_invalid_address
        given memory = []TernaryWord{TernaryWord{.raw = 0}}
        and   word = TernaryWord{.raw = 0xABC}
        and   success = mem_store(memory, 999, word)
        then success == false

    test mem_load_aligned_success
        given memory = []TernaryWord{TernaryWord{.raw = 0x123}, TernaryWord{.raw = 0x456}}
        and   value = mem_load_aligned(memory, 3, 3)
        then value.raw == 0x456

    test mem_load_aligned_fail
        given memory = []TernaryWord{TernaryWord{.raw = 0x123}, TernaryWord{.raw = 0x456}}
        and   value = mem_load_aligned(memory, 2, 3)
        then value.raw == 0

    test mem_store_aligned_success
        given memory = []TernaryWord{TernaryWord{.raw = 0}, TernaryWord{.raw = 0}}
        and   word = TernaryWord{.raw = 0xABC}
        and   success = mem_store_aligned(memory, 3, word, 3)
        and   result = mem_load(memory, 3)
        then success == true and result.raw == 0xABC

    test mem_store_aligned_fail
        given memory = []TernaryWord{TernaryWord{.raw = 0}, TernaryWord{.raw = 0}}
        and   word = TernaryWord{.raw = 0xABC}
        and   success = mem_store_aligned(memory, 2, word, 3)
        then success == false

    test mem_push_pop_roundtrip
        given memory = []TernaryWord{TernaryWord{.raw = 0}, TernaryWord{.raw = 0}, TernaryWord{.raw = 0}}
        and   sp : u32 = 3
        and   word = TernaryWord{.raw = 0xDEF}
        and   push_ok = mem_push(memory, &sp, word)
        and   popped = mem_pop(memory, &sp)
        then push_ok == true and popped.raw == 0xDEF and sp == 3

    test mem_push_overflow
        given memory = []TernaryWord{}
        and   sp : u32 = 0
        and   word = TernaryWord{.raw = 0x123}
        and   success = mem_push(memory, &sp, word)
        then success == false

    test mem_block_copy_success
        given src = []TernaryWord{TernaryWord{.raw = 0x111}, TernaryWord{.raw = 0x222}}
        and   dst = []TernaryWord{TernaryWord{.raw = 0}, TernaryWord{.raw = 0}}
        and   success = mem_copy(dst, 0, src, 0, 2)
        and   v0 = mem_load(dst, 0)
        and   v1 = mem_load(dst, 1)
        then success == true and v0.raw == 0x111 and v1.raw == 0x222

    test mem_block_copy_overlap
        given memory = []TernaryWord{TernaryWord{.raw = 0x111}, TernaryWord{.raw = 0x222}, TernaryWord{.raw = 0x333}}
        and   success = mem_copy(memory, 0, memory, 1, 2)
        and   v0 = mem_load(memory, 0)
        and   v1 = mem_load(memory, 1)
        then success == true and v0.raw == 0x222 and v1.raw == 0x333

    test mem_fill_success
        given memory = []TernaryWord{TernaryWord{.raw = 0}, TernaryWord{.raw = 0}, TernaryWord{.raw = 0}}
        and   word = TernaryWord{.raw = 0xABC}
        and   success = mem_fill(memory, 0, word, 2)
        then success == true

    test virt_to_phys_valid
        given virt = 10
        and   base = 100
        and   limit = 50
        and   phys = virt_to_phys(virt, base, limit)
        then phys == 110

    test virt_to_phys_out_of_range
        given virt = 100
        and   base = 10
        and   limit = 50
        and   phys = virt_to_phys(virt, base, limit)
        then phys == 0xFFFFFFFF

    test word_pack_extract_trit
        given word = TernaryWord{.raw = 0}
        and   packed = word_pack_trit(word, 5, TRIT_POS)
        and   extracted = word_extract_trit(packed, 5)
        then extracted == TRIT_POS

    test word_pack_neg_trit
        given word = TernaryWord{.raw = 0xFFFFFFFF}
        and   packed = word_pack_trit(word, 0, TRIT_NEG)
        and   extracted = word_extract_trit(packed, 0)
        then extracted == TRIT_NEG

    test word_pack_zero_trit
        given word = TernaryWord{.raw = 0xFFFFFFFF}
        and   packed = word_pack_trit(word, 1, TRIT_ZERO)
        and   extracted = word_extract_trit(packed, 1)
        then extracted == TRIT_ZERO

    invariant mem_size_is_power_of_three
        assert MEM_SIZE == 27 or MEM_SIZE == 19683 or MEM_SIZE == 531441

    invariant mem_addr_width_matches_word_size
        assert MEM_ADDR_WIDTH == WORD_SIZE

    invariant mem_alignment_power_of_three
        assert ALIGNMENT == 1 or ALIGNMENT == 3 or ALIGNMENT == 9

    invariant mem_permissions_valid
        assert PERM_READ == 0x1
        assert PERM_WRITE == 0x2
        assert PERM_EXEC == 0x4

    invariant mem_load_preserves_memory
        given memory = []TernaryWord{TernaryWord{.raw = 0x123}, TernaryWord{.raw = 0x456}}
        and   before = mem_load(memory, 1)
        and   after = mem_load(memory, 1)
        assert before.raw == after.raw

    invariant mem_store_changes_memory
        given memory = []TernaryWord{TernaryWord{.raw = 0x123}}
        and   word = TernaryWord{.raw = 0xABC}
        and   mem_store(memory, 0, word)
        and   result = mem_load(memory, 0)
        assert result.raw == 0xABC

    invariant sp_decrements_on_push
        given memory = []TernaryWord{TernaryWord{.raw = 0}}
        and   sp_before : u32 = 5
        and   mem_push(memory, &sp_before, TernaryWord{.raw = 0})
        assert sp_before < 5

    invariant sp_increments_on_pop
        given memory = []TernaryWord{TernaryWord{.raw = 0x123}}
        and   sp_before : u32 = 3
        and   mem_pop(memory, &sp_before)
        assert sp_before > 3

    invariant mem_copy_handles_overlap
        given memory = []TernaryWord{TernaryWord{.raw = 0x111}, TernaryWord{.raw = 0x222}, TernaryWord{.raw = 0x333}}
        and   mem_copy(memory, 0, memory, 1, 2)
        and   v0 = mem_load(memory, 0)
        and   v1 = mem_load(memory, 1)
        // After copy: [0x222, 0x333] (forward copy from offset 1)
        assert v0.raw == 0x222 and v1.raw == 0x333

    invariant mem_protect_modifies_permissions
        given prot = []u8{0, 0, 0}
        and   mem_protect([]TernaryWord{}, 1, PERM_READ, prot)
        and   new_perm = prot[1]
        assert new_perm == PERM_READ

    invariant word_extract_trit_range
        for (const i) |idx| in [0usize, 13, 26] {
            const word = TernaryWord{.raw = 0};
            const trit = word_extract_trit(word, idx);
            assert trit == TRIT_ZERO or trit == TRIT_NEG or trit == TRIT_POS;
        }

    invariant stack_base_is_highest_address
        assert STACK_BASE == MEM_SIZE - 1

    invariant virt_to_phys_zero_maps_invalid
        assert virt_to_phys(0, 0, 0) == 0  // Base 0, limit 0 -> addr 0 valid
        assert virt_to_phys(1, 0, 0) == 0xFFFFFFFF  // Out of limit

    bench mem_load_latency
        measure: nanoseconds to mem_load([]TernaryWord{TernaryWord{.raw = 0}}, 10)
        target: < 100ns

    bench mem_store_latency
        measure: nanoseconds to mem_store([]TernaryWord{TernaryWord{.raw = 0}}, 10, TernaryWord{.raw = 0x123})
        target: < 100ns

    bench mem_copy_latency
        measure: nanoseconds to mem_copy([]TernaryWord{.raw = 0, 0, 0}, 0, []TernaryWord{.raw = 0, 0, 0}, 10)
        target: < 500ns

    bench mem_fill_latency
        measure: nanoseconds to mem_fill([]TernaryWord{.raw = 0}, 0, TernaryWord{.raw = 0xABC}, 10)
        target: < 400ns

    bench word_pack_trit_latency
        measure: nanoseconds to word_pack_trit(TernaryWord{.raw = 0}, 13, TRIT_POS)
        target: < 50ns

    bench word_extract_trit_latency
        measure: nanoseconds to word_extract_trit(TernaryWord{.raw = (0x2u32 << 26)}, 13)
        target: < 50ns
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/isa/ternary_arithmetic.t27
// Ternary Arithmetic Operations Specification
// Ring 064 - Balanced ternary arithmetic for T27
// Defines addition, subtraction, multiplication, and division
// phi^2 + 1/phi^2 = 3 | TRINITY

module TernaryArithmetic {
    use base::types;

    // =====================================================
    // 1. Ternary Values and Constants
    // =========================================================================

    // Balanced ternary values
    const TRIT_NEG : i32 = -1;   // Negative
    const TRIT_ZERO : i32 = 0;   // Zero
    const TRIT_POS : i32 = 1;    // Positive

    // Trit range for validation
    const MIN_TRIT : i32 = -1;
    const MAX_TRIT : i32 = 1;

    // Number of trits in a word (configurable)
    const TRITS_PER_WORD : usize = 27;  // 3^27 states (~7.6 trillion)

    // =====================================================
    // 2. Single Trit Addition
    // =========================================================================

    // trit_add(a: i32, b: i32, carry_in: i32) -> TritAddResult
    // Add two trits with carry in, return sum and carry out
    // Balanced ternary: -1, 0, 1
    // Result can be -2, -1, 0, 1, 2 (needs carry)
    fn trit_add(a: i32, b: i32, carry_in: i32) -> TritAddResult {
        var sum = a + b + carry_in;

        // Normalize balanced ternary
        var carry_out : i32 = 0;

        if (sum > 1) {
            // 2 or 3 -> 1 or 0 with carry +1
            carry_out = 1;
            sum = sum - 3;
        } else if (sum < -1) {
            // -2 or -3 -> -1 or 0 with carry -1
            carry_out = -1;
            sum = sum + 3;
        }

        return TritAddResult{
            .sum = sum,
            .carry_out = carry_out,
        };
    }

    struct TritAddResult {
        sum : i32,
        carry_out : i32,
    }

    // =====================================================
    // 3. Single Trit Subtraction
    // =========================================================================

    // trit_sub(a: i32, b: i32, borrow_in: i32) -> TritSubResult
    // Subtract b from a with borrow in
    fn trit_sub(a: i32, b: i32, borrow_in: i32) -> TritSubResult {
        // Subtraction = addition with negated subtrahend
        const neg_b = -b;
        const result = trit_add(a, neg_b, borrow_in);

        // Borrow is just negative carry in balanced ternary
        return TritSubResult{
            .diff = result.sum,
            .borrow_out = -result.carry_out,
        };
    }

    struct TritSubResult {
        diff : i32,
        borrow_out : i32,
    }

    // =====================================================
    // 4. Single Trit Multiplication
    // =========================================================================

    // trit_mul(a: i32, b: i32) -> i32
    // Multiply two trits
    // Result: -1, 0, or 1 (no carry needed for single trit)
    fn trit_mul(a: i32, b: i32) -> i32 {
        return a * b;
    }

    // =====================================================
    // 5. Word-Level Addition
    // =========================================================================

    // ternary_word_add(a: []i32, b: []i32, len: usize) -> WordAddResult
    // Add two ternary words with carry propagation
    fn ternary_word_add(a: []i32, b: []i32, len: usize) -> WordAddResult {
        var result : WordAddResult = undefined;
        var carry : i32 = 0;
        var i : usize = 0;

        while (i < len) {
            const add_result = trit_add(a[i], b[i], carry);
            result.sum[i] = add_result.sum;
            carry = add_result.carry_out;
            i = i + 1;
        }

        result.carry_out = carry;
        result.overflow = carry != 0;

        return result;
    }

    struct WordAddResult {
        sum : [TRITS_PER_WORD]i32,
        carry_out : i32,
        overflow : bool,
    }

    // =====================================================
    // 6. Word-Level Subtraction
    // =========================================================================

    // ternary_word_sub(a: []i32, b: []i32, len: usize) -> WordSubResult
    // Subtract b from a with borrow propagation
    fn ternary_word_sub(a: []i32, b: []i32, len: usize) -> WordSubResult {
        var result : WordSubResult = undefined;
        var borrow : i32 = 0;
        var i : usize = 0;

        while (i < len) {
            const sub_result = trit_sub(a[i], b[i], borrow);
            result.diff[i] = sub_result.diff;
            borrow = sub_result.borrow_out;
            i = i + 1;
        }

        result.borrow_out = borrow;
        result.underflow = borrow != 0;

        return result;
    }

    struct WordSubResult {
        diff : [TRITS_PER_WORD]i32,
        borrow_out : i32,
        underflow : bool,
    }

    // =====================================================
    // 7. Ternary to Decimal Conversion
    // =========================================================================

    // ternary_to_decimal(trits: []i32, len: usize) -> i64
    // Convert balanced ternary to decimal integer
    fn ternary_to_decimal(trits: []i32, len: usize) -> i64 {
        var result : i64 = 0;
        var power : i64 = 1;
        var i : usize = 0;

        while (i < len) {
            result = result + @as(i64, @intCast(trits[i])) * power;
            power = power * 3;
            i = i + 1;
        }

        return result;
    }

    // decimal_to_ternary(value: i64, trits: []i32, len: usize) -> usize
    // Convert decimal integer to balanced ternary
    // Returns number of trits used
    fn decimal_to_ternary(value: i64, trits: []i32, len: usize) -> usize {
        var val = value;
        var i : usize = 0;

        while (i < len and val != 0) {
            const rem = @rem(val, 3);

            if (rem == 2) {
                trits[i] = TRIT_NEG;
                val = val / 3 + 1;
            } else if (rem == -2) {
                trits[i] = TRIT_POS;
                val = val / 3 - 1;
            } else {
                trits[i] = @as(i32, @intCast(rem));
                val = val / 3;
            }

            i = i + 1;
        }

        // Pad remaining trits with zero
        while (i < len) {
            trits[i] = TRIT_ZERO;
            i = i + 1;
        }

        // Find actual length used
        var actual_len : usize = len;
        while (actual_len > 1 and trits[actual_len - 1] == TRIT_ZERO) {
            actual_len = actual_len - 1;
        }

        return actual_len;
    }

    // =====================================================
    // 8. Validation Functions
    // =========================================================================

    // is_valid_trit(t: i32) -> bool
    // Check if a value is a valid trit
    fn is_valid_trit(t: i32) -> bool {
        return t >= MIN_TRIT and t <= MAX_TRIT;
    }

    // validate_trits(trits: []i32, len: usize) -> bool
    // Validate all trits in an array
    fn validate_trits(trits: []i32, len: usize) -> bool {
        var i : usize = 0;
        while (i < len) {
            if (!is_valid_trit(trits[i])) {
                return false;
            }
            i = i + 1;
        }
        return true;
    }

    // =====================================================
    // 9. Comparison Operations
    // =========================================================================

    // ternary_compare(a: []i32, b: []i32, len: usize) -> i32
    // Compare two ternary words
    // Returns -1 if a < b, 0 if a == b, 1 if a > b
    fn ternary_compare(a: []i32, b: []i32, len: usize) -> i32 {
        // Compare from most significant trit
        var i : i64 = @as(i64, @intCast(len)) - 1;

        while (i >= 0) {
            const idx = @as(usize, @intCast(i));

            if (a[idx] < b[idx]) {
                return -1;
            } else if (a[idx] > b[idx]) {
                return 1;
            }

            i = i - 1;
        }

        return 0;
    }

    // =====================================================
    // 10. TDD - Tests
    // =========================================================================

    test trit_add_basic
        // 1 + 1 = 2 -> -1 with carry +1 (balanced ternary: 2 = -1 + 3)
        var r1 = trit_add(TRIT_POS, TRIT_POS, TRIT_ZERO);
        assert r1.sum == TRIT_NEG
        assert r1.carry_out == TRIT_POS

        // -1 + -1 = -2 -> 1 with carry -1
        var r2 = trit_add(TRIT_NEG, TRIT_NEG, TRIT_ZERO);
        assert r2.sum == TRIT_POS
        assert r2.carry_out == TRIT_NEG

        // 1 + -1 = 0 with no carry
        var r3 = trit_add(TRIT_POS, TRIT_NEG, TRIT_ZERO);
        assert r3.sum == TRIT_ZERO
        assert r3.carry_out == TRIT_ZERO

        // 0 + 0 = 0 with no carry
        var r4 = trit_add(TRIT_ZERO, TRIT_ZERO, TRIT_ZERO);
        assert r4.sum == TRIT_ZERO
        assert r4.carry_out == TRIT_ZERO

    test trit_sub_basic
        // 1 - 1 = 0 with no borrow
        var r1 = trit_sub(TRIT_POS, TRIT_POS, TRIT_ZERO);
        assert r1.diff == TRIT_ZERO
        assert r1.borrow_out == TRIT_ZERO

        // 0 - 1 = -1 with no borrow
        var r2 = trit_sub(TRIT_ZERO, TRIT_POS, TRIT_ZERO);
        assert r2.diff == TRIT_NEG
        assert r2.borrow_out == TRIT_ZERO

        // 1 - 0 = 1 with no borrow
        var r3 = trit_sub(TRIT_POS, TRIT_ZERO, TRIT_ZERO);
        assert r3.diff == TRIT_POS
        assert r3.borrow_out == TRIT_ZERO

    test trit_mul_basic
        assert trit_mul(TRIT_POS, TRIT_POS) == TRIT_POS
        assert trit_mul(TRIT_POS, TRIT_NEG) == TRIT_NEG
        assert trit_mul(TRIT_NEG, TRIT_POS) == TRIT_NEG
        assert trit_mul(TRIT_NEG, TRIT_NEG) == TRIT_POS
        assert trit_mul(TRIT_ZERO, TRIT_POS) == TRIT_ZERO
        assert trit_mul(TRIT_POS, TRIT_ZERO) == TRIT_ZERO
        assert trit_mul(TRIT_ZERO, TRIT_NEG) == TRIT_ZERO
        assert trit_mul(TRIT_NEG, TRIT_ZERO) == TRIT_ZERO

    test ternary_to_decimal_basic
        var t1 : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_ZERO};  // 1
        assert ternary_to_decimal(&t1, 3) == 1

        var t2 : [3]i32 = [_]i32{TRIT_NEG, TRIT_ZERO, TRIT_ZERO};  // -1
        assert ternary_to_decimal(&t2, 3) == -1

        var t3 : [3]i32 = [_]i32{TRIT_ZERO, TRIT_POS, TRIT_ZERO};  // 3
        assert ternary_to_decimal(&t3, 3) == 3

        var t4 : [3]i32 = [_]i32{TRIT_POS, TRIT_POS, TRIT_ZERO};  // 1 + 3 = 4
        assert ternary_to_decimal(&t4, 3) == 4

    test decimal_to_ternary_basic
        var t1 : [5]i32 = undefined;
        decimal_to_ternary(0, &t1, 5);
        assert t1[0] == TRIT_ZERO

        var t2 : [5]i32 = undefined;
        decimal_to_ternary(1, &t2, 5);
        assert t2[0] == TRIT_POS
        assert t2[1] == TRIT_ZERO

        var t3 : [5]i32 = undefined;
        decimal_to_ternary(-1, &t3, 5);
        assert t3[0] == TRIT_NEG
        assert t3[1] == TRIT_ZERO

        var t4 : [5]i32 = undefined;
        decimal_to_ternary(4, &t4, 5);
        assert t4[0] == TRIT_POS
        assert t4[1] == TRIT_POS

    test is_valid_trit_check
        assert is_valid_trit(TRIT_NEG) == true
        assert is_valid_trit(TRIT_ZERO) == true
        assert is_valid_trit(TRIT_POS) == true
        assert is_valid_trit(2) == false
        assert is_valid_trit(-2) == false

    test ternary_compare_basic
        var a : [3]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_ZERO};  // 1
        var b : [3]i32 = [_]i32{TRIT_ZERO, TRIT_ZERO, TRIT_ZERO};  // 0
        assert ternary_compare(&a, &b, 3) == 1
        assert ternary_compare(&b, &a, 3) == -1
        assert ternary_compare(&a, &a, 3) == 0

    // =====================================================
    // 11. TDD - Invariants
    // =========================================================================

    invariant trit_add_commutative
        // Trit addition is commutative
        const vals = [_]i32{TRIT_NEG, TRIT_ZERO, TRIT_POS};
        var i : usize = 0;
        while (i < 3) {
            var j : usize = 0;
            while (j < 3) {
                var k : usize = 0;
                while (k < 3) {
                    const r1 = trit_add(vals[i], vals[j], vals[k]);
                    const r2 = trit_add(vals[j], vals[i], vals[k]);
                    assert r1.sum == r2.sum
                    assert r1.carry_out == r2.carry_out
                    k = k + 1;
                }
                j = j + 1;
            }
            i = i + 1;
        }

    invariant trit_add_associative
        // Trit addition is associative (simplified check)
        const vals = [_]i32{TRIT_NEG, TRIT_ZERO, TRIT_POS};
        var i : usize = 0;
        while (i < 3) {
            var j : usize = 0;
            while (j < 3) {
                var k : usize = 0;
                while (k < 3) {
                    const r1 = trit_add(trit_add(vals[i], vals[j], TRIT_ZERO).sum, vals[k], TRIT_ZERO);
                    const r2 = trit_add(vals[i], trit_add(vals[j], vals[k], TRIT_ZERO).sum, TRIT_ZERO);
                    assert r1.sum == r2.sum
                    k = k + 1;
                }
                j = j + 1;
            }
            i = i + 1;
        }

    invariant trit_mul_commutative
        // Trit multiplication is commutative
        const vals = [_]i32{TRIT_NEG, TRIT_ZERO, TRIT_POS};
        var i : usize = 0;
        while (i < 3) {
            var j : usize = 0;
            while (j < 3) {
                assert trit_mul(vals[i], vals[j]) == trit_mul(vals[j], vals[i])
                j = j + 1;
            }
            i = i + 1;
        }

    invariant trit_mul_identity
        // 1 is the multiplicative identity
        const vals = [_]i32{TRIT_NEG, TRIT_ZERO, TRIT_POS};
        var i : usize = 0;
        while (i < 3) {
            assert trit_mul(vals[i], TRIT_POS) == vals[i]
            assert trit_mul(TRIT_POS, vals[i]) == vals[i]
            i = i + 1;
        }

    invariant trit_mul_zero_property
        // 0 is the multiplicative zero
        const vals = [_]i32{TRIT_NEG, TRIT_ZERO, TRIT_POS};
        var i : usize = 0;
        while (i < 3) {
            assert trit_mul(vals[i], TRIT_ZERO) == TRIT_ZERO
            assert trit_mul(TRIT_ZERO, vals[i]) == TRIT_ZERO
            i = i + 1;
        }

    invariant conversion_roundtrip
        // Decimal to ternary to decimal should be identity (for small values)
        var test_values : [10]i64 = [_]i64{-40, -10, -5, -1, 0, 1, 5, 10, 13, 40};
        var i : usize = 0;
        while (i < 10) {
            var trits : [10]i32 = undefined;
            decimal_to_ternary(test_values[i], &trits, 10);
            const result = ternary_to_decimal(&trits, 10);
            assert result == test_values[i]
            i = i + 1;
        }

    // =====================================================
    // 12. TDD - Benchmarks
    // =========================================================================

    bench trit_add_performance
        // Measure: cycles to compute 1000 trit additions
        // Target: < 500 cycles
        const vals = [_]i32{TRIT_NEG, TRIT_ZERO, TRIT_POS};
        @setEvalBranchQuota(10000);
        var result : TritAddResult = undefined;
        var idx : usize = 0;
        for (0..1000) |_| {
            result = trit_add(vals[idx % 3], vals[(idx + 1) % 3], TRIT_ZERO);
            idx = idx + 1;
        }
        _ = result;

    bench trit_mul_performance
        // Measure: cycles to compute 1000 trit multiplications
        // Target: < 300 cycles
        const vals = [_]i32{TRIT_NEG, TRIT_ZERO, TRIT_POS};
        @setEvalBranchQuota(10000);
        var result : i32 = 0;
        var idx : usize = 0;
        for (0..1000) |_| {
            result = trit_mul(vals[idx % 3], vals[(idx + 1) % 3]);
            idx = idx + 1;
        }
        _ = result;

    bench conversion_performance
        // Measure: cycles to convert 100 decimal values to ternary
        // Target: < 5000 cycles
        var trits : [10]i32 = undefined;
        @setEvalBranchQuota(10000);
        for (0..100) |i| {
            decimal_to_ternary(@as(i64, @intCast(i)) - 50, &trits, 10);
        }

    bench comparison_performance
        // Measure: cycles to compare 100 ternary word pairs
        // Target: < 3000 cycles
        var a : [10]i32 = [_]i32{TRIT_POS, TRIT_ZERO, TRIT_NEG, TRIT_POS, TRIT_ZERO, TRIT_NEG, TRIT_POS, TRIT_ZERO, TRIT_NEG, TRIT_POS};
        var b : [10]i32 = [_]i32{TRIT_ZERO, TRIT_POS, TRIT_NEG, TRIT_POS, TRIT_NEG, TRIT_ZERO, TRIT_NEG, TRIT_POS, TRIT_ZERO, TRIT_NEG};
        @setEvalBranchQuota(10000);
        var result : i32 = 0;
        for (0..100) |_| {
            result = ternary_compare(&a, &b, 10);
        }
        _ = result;
}

