// lsp/schema.t27 — LSP Base Types
// Position, Range, Diagnostic definitions for Language Server Protocol
// φ² + 1/φ² = 3 | TRINITY

module lsp-schema;

// ============================================================================
// Imports
// ============================================================================

use tritype-base::usize;

// ============================================================================
// Constants
// ============================================================================

/// Default character offset for start of document
pub const ZERO_POSITION : usize = 0;

/// Maximum line number in diagnostic reports
pub const MAX_LINE : usize = 65535;

/// Maximum character position on a line
pub const MAX_CHAR : usize = 65535;

/// Default protocol version
pub const LSP_VERSION : [4]u8 = "3.17";

// ============================================================================
// Types
// ============================================================================

/// Line and character position in a document
/// Zero-based: line 0, char 0 is first position
pub const Position = struct {
    line : usize,
    character : usize,
};

/// Range between two positions (start exclusive, end inclusive)
/// Used for: selection, code action, diagnostic spans
pub const Range = struct {
    start : Position,
    end : Position,
};

/// Location in a specific document
/// Combines URI with range within that document
pub const Location = struct {
    uri : []u8,
    range : Range,
};

/// Diagnostic severity levels
/// Order: HINT < INFO < WARNING < ERROR
pub const DiagnosticSeverity = enum(u8) {
    hint = 0,
    info = 1,
    warning = 2,
    error = 3,
};

/// Diagnostic tag for code actions
pub const DiagnosticTag = enum(u8) {
    unnecessary = 0,
    deprecated = 1,
};

/// Code action for quick fixes
pub const CodeAction = struct {
    title : []u8,
    kind : CodeActionKind,
    diagnostics : []Diagnostic,
    edit : WorkspaceEdit,
};

/// Code action kind
pub const CodeActionKind = enum(u8) {
    quick_fix = 0,
    refactor = 1,
    refactor_extract = 2,
    refactor_inline = 3,
};

/// Workspace edit for code changes
pub const WorkspaceEdit = struct {
    changes : []TextDocumentEdit,
};

/// Single document edit
pub const TextDocumentEdit = struct {
    range : Range,
    new_text : []u8,
};

/// Diagnostic information
pub const Diagnostic = struct {
    range : Range,
    severity : DiagnosticSeverity,
    code : []u8,
    source : []u8,
    message : []u8,
    tags : []DiagnosticTag,
};

/// Text document synchronization kind
pub const TextDocumentSyncKind = enum(u8) {
    full = 0,
    incremental = 1,
};

/// Text document item for opening
pub const TextDocumentItem = struct {
    uri : []u8,
    version : usize,
    language_id : []u8,
    text : []u8,
};

/// Completion item for code completion
pub const CompletionItem = struct {
    label : []u8,
    kind : CompletionItemKind,
    detail : []u8,
    documentation : []u8,
    sort_text : []u8,
    filter_text : []u8,
    insert_text : []u8,
};

/// Completion item kind
pub const CompletionItemKind = enum(u8) {
    text = 0,
    method = 1,
    function = 2,
    constructor = 3,
    field = 4,
    variable = 5,
    class = 6,
    interface = 7,
    module = 8,
    property = 9,
    unit = 10,
    value = 11,
    enum = 12,
    keyword = 13,
    snippet = 14,
    color = 15,
    file = 16,
    reference = 17,
    folder = 18,
    enum_member = 19,
    constant = 20,
    struct = 21,
    event = 22,
    operator = 23,
    type_parameter = 24,
};

/// Signature help information
pub const SignatureInformation = struct {
    label : []u8,
    documentation : []u8,
    parameters : []ParameterInformation,
};

/// Parameter in signature help
pub const ParameterInformation = struct {
    label : []u8,
    documentation : []u8,
};

/// Hover response
pub const Hover = struct {
    contents : []u8,
    range : Range,
};

/// Document symbol kind
pub const SymbolKind = enum(u8) {
    file = 0,
    module = 1,
    namespace = 2,
    package = 3,
    class = 4,
    method = 5,
    property = 6,
    field = 7,
    constructor = 8,
    enum = 9,
    interface = 10,
    function = 11,
    variable = 12,
    constant = 13,
    string = 14,
    number = 15,
    boolean = 16,
    array = 17,
    object = 18,
    key = 19,
    null = 20,
    enum_member = 21,
    struct = 22,
    event = 23,
    operator = 24,
    type_parameter = 25,
};

/// Document symbol
pub const DocumentSymbol = struct {
    name : []u8,
    detail : []u8,
    kind : SymbolKind,
    range : Range,
    selection_range : Range,
    children : []DocumentSymbol,
};

/// Inlay hint kind
pub const InlayHintKind = enum(u8) {
    type = 0,
    parameter = 1,
};

/// Inlay hint
pub const InlayHint = struct {
    position : Position,
    label : []u8,
    kind : InlayHintKind,
    padding_left : bool,
    padding_right : bool,
};

/// Code lens for code actions
pub const CodeLens = struct {
    range : Range,
    command : Command,
};

/// Command
pub const Command = struct {
    title : []u8,
    command : []u8,
    arguments : []u8,
};

// ============================================================================
// Functions
// ============================================================================

/// Create position at zero
pub fn position_zero() Position {
    return Position{ .line = 0, .character = 0 };
}

/// Create range from positions
pub fn range_from_positions(start: Position, end: Position) Range {
    return Range{ .start = start, .end = end };
}

/// Create range from line/char values
pub fn range_create(start_line: usize, start_char: usize, end_line: usize, end_char: usize) Range {
    const start = Position{ .line = start_line, .character = start_char };
    const end = Position{ .line = end_line, .character = end_char };
    return Range{ .start = start, .end = end };
}

/// Create location from URI and range
pub fn location_create(uri: []u8, start_line: usize, start_char: usize, end_line: usize, end_char: usize) Location {
    const range = range_create(start_line, start_char, end_line, end_char);
    return Location{ .uri = uri, .range = range };
}

/// Create diagnostic
pub fn diagnostic_create(range: Range, severity: DiagnosticSeverity, message: []u8, source: []u8) Diagnostic {
    return Diagnostic{
        .range = range,
        .severity = severity,
        .code = "",
        .source = source,
        .message = message,
        .tags = &[_]DiagnosticTag{},
    };
}

/// Create completion item
pub fn completion_item_create(label: []u8, kind: CompletionItemKind, insert_text: []u8) CompletionItem {
    return CompletionItem{
        .label = label,
        .kind = kind,
        .detail = "",
        .documentation = "",
        .sort_text = "",
        .filter_text = "",
        .insert_text = insert_text,
    };
}

/// Create inlay hint
pub fn inlay_hint_create(position: Position, label: []u8, kind: InlayHintKind) InlayHint {
    return InlayHint{
        .position = position,
        .label = label,
        .kind = kind,
        .padding_left = false,
        .padding_right = false,
    };
}

/// Create document symbol
pub fn document_symbol_create(name: []u8, kind: SymbolKind, range: Range) DocumentSymbol {
    return DocumentSymbol{
        .name = name,
        .detail = "",
        .kind = kind,
        .range = range,
        .selection_range = range,
        .children = &[_]DocumentSymbol{},
    };
}

/// Check if position is zero
pub fn position_is_zero(pos: Position) bool {
    return pos.line == 0 and pos.character == 0;
}

/// Check if range is empty (start == end)
pub fn range_is_empty(r: Range) bool {
    return r.start.line == r.end.line and r.start.character == r.end.character;
}

/// Get range length in characters (simplified)
pub fn range_length(r: Range) usize {
    if (r.start.line == r.end.line) {
        if (r.end.character > r.start.character) {
            return r.end.character - r.start.character;
        }
    }
    return 0;
}

/// Compare two positions
pub fn position_compare(a: Position, b: Position) i8 {
    if (a.line < b.line) {
        return -1;
    } else if (a.line > b.line) {
        return 1;
    } else {
        if (a.character < b.character) {
            return -1;
        } else if (a.character > b.character) {
            return 1;
        } else {
            return 0;
        }
    }
}

/// Check if position is within range
pub fn range_contains_position(r: Range, pos: Position) bool {
    const after_start = position_compare(pos, r.start) >= 0;
    const before_end = position_compare(pos, r.end) < 0;
    return after_start and before_end;
}

/// Format severity as string
pub fn severity_to_string(sev: DiagnosticSeverity) []u8 {
    return switch (sev) {
        .error => "error",
        .warning => "warning",
        .info => "info",
        .hint => "hint",
    };
}

