test "lsp_position_zero_is_zero" {
    const pos = position_zero();
    try std.testing.expect(pos.line == 0);
    try std.testing.expect(pos.character == 0);
}

test "lsp_range_from_positions" {
    const start = Position{ .line = 5, .character = 10 };
    const end = Position{ .line = 5, .character = 20 };
    const r = range_from_positions(start, end);
    try std.testing.expect(r.start.line == 5);
    try std.testing.expect(r.end.character == 20);
