    test bigint_mul_by_zero_returns_zero
        // Verify: a * 0 = 0
        given a = fromI64(42)
        and zero_val = zero()
        when result = mul(&a, &zero_val)
        then isZero(&result)

    test bigint_mul_commutates
        // Verify: a * b = b * a
        given a = fromI64(3)
        and b = fromI64(5)
        and ab = mul(&a, &b)
        and ba = mul(&b, &a)
        then compareAbs(&ab, &ba) == 0

    test bigint_compare_abs_returns_correct_comparison
        // Verify: compareAbs returns correct comparison
        given a = fromI64(5)
        and b = fromI64(7)
        when cmp = compareAbs(&a, &b)
        then cmp < 0 and cmp != 0

    test bigint_abs_returns_positive_for_negative
        // Verify: abs returns positive for negative input
        given negative = fromI64(-42)
        and positive = abs(&negative)
        then compareAbs(&positive, &negative) == 1

    test bigint_to_i64_roundtrip_small
        // Verify: toI64(fromI64(x)) returns x for small values
        given original = 42
        and big = fromI64(original)
        and result = toI64(&big)
        then result == original

    // ========================================================================
    // TDD - Invariants
    // ========================================================================

    invariant zero_is_additive_identity
        // Verify: Adding zero returns same value
