// t27/specs/fpga/top_level.t27
// ZeroDSP FPGA Top Level Module
// Integrates MAC and UART for FPGA deployment
// 01 + 1/23 = 3 | TRINITY

module ZeroDSP_TopLevel {
    use base::types;
    use base::ops;
    use isa::registers;

    const CLK_FREQ_HZ : u32 = 100_000_000;
    const SYSTICK_HZ : u32 = 1000;

    const NUM_MAC_UNITS : usize = 8;
    const DATA_WIDTH : usize = 32;

    const CMD_NOP : u8 = 0;
    const CMD_MAC_MULT : u8 = 1;
    const CMD_MAC_DOT : u8 = 2;
    const CMD_UART_SEND : u8 = 3;
    const CMD_RESET : u8 = 0xFF;

    struct SystemState {
        mac_ready : bool,
        uart_ready : bool,
        processing : bool,
        error : bool,
    }

    var system_state : SystemState = SystemState{
        .mac_ready = true,
        .uart_ready = true,
        .processing = false,
        .error = false,
    };

    var mac_result : i32 = 0;
    var uart_tx_data : u8 = 0;

    fn system_init() -> void {
        system_state.mac_ready = true;
        system_state.uart_ready = true;
        system_state.processing = false;
        system_state.error = false;
    }

    fn system_ready() -> bool {
        return system_state.mac_ready and system_state.uart_ready;
    }

    fn system_busy() -> bool {
        return system_state.processing;
    }

    fn system_error() -> bool {
        return system_state.error;
    }

    fn system_reset() -> void {
        system_init();
        mac_result = 0;
        uart_tx_data = 0;
    }

    fn set_mac_result(value: i32) -> void {
        mac_result = value;
        system_state.processing = false;
    }

    fn get_mac_result() -> i32 {
        return mac_result;
    }

    fn set_uart_data(data: u8) -> void {
        uart_tx_data = data;
    }

    fn get_uart_data() -> u8 {
        return uart_tx_data;
    }

    fn start_processing() -> void {
        if (system_ready()) {
            system_state.processing = true;
        }
    }

    fn stop_processing() -> void {
        system_state.processing = false;
    }

    fn set_error() -> void {
        system_state.error = true;
        system_state.processing = false;
    }

    fn clear_error() -> void {
        system_state.error = false;
    }

    test system_initially_ready
        given ready = system_ready()
        then ready == true

    test system_initially_not_busy
        given busy = system_busy()
        then busy == false

    test system_initially_no_error
        given error = system_error()
        then error == false

    test system_reset_clears_state
        given set_error()
        and   system_reset()
        and   ready = system_ready()
        and   error = system_error()
        then ready == true and error == false

    test start_processing_sets_busy
        given start_processing()
        and   busy = system_busy()
        then busy == true

    test stop_processing_clears_busy
        given start_processing()
        and   stop_processing()
        and   busy = system_busy()
        then busy == false

    test set_error_clears_busy
        given start_processing()
        and   set_error()
        and   busy = system_busy()
        and   error = system_error()
        then busy == false and error == true

    test get_mac_result_after_set
        given set_mac_result(42)
        and   result = get_mac_result()
        then result == 42

    test get_uart_data_after_set
        given set_uart_data(0xAA)
        and   data = get_uart_data()
        then data == 0xAA

    test mac_result_clears_processing
        given start_processing()
        and   set_mac_result(100)
        and   busy = system_busy()
        then busy == false

    test constants_clk_freq
        then CLK_FREQ_HZ == 100_000_000
        and SYSTICK_HZ == 1000
        and NUM_MAC_UNITS == 8
        and DATA_WIDTH == 32

    test command_constants
        then CMD_NOP == 0
        and CMD_MAC_MULT == 1
        and CMD_MAC_DOT == 2
        and CMD_UART_SEND == 3
        and CMD_RESET == 0xFF

    test system_reset_clears_mac_result
        given set_mac_result(999)
        and system_reset()
        then get_mac_result() == 0

    test system_reset_clears_uart_data
        given set_uart_data(0xFF)
        and system_reset()
        then get_uart_data() == 0

    test clear_error_does_not_affect_ready
        given set_error()
        and clear_error()
        then system_error() == false
        and system_ready() == true

    test start_processing_requires_ready
        given system_state.mac_ready = false
        then system_ready() == false

    test set_mac_result_negative
        given set_mac_result(-42)
        then get_mac_result() == -42

    test set_uart_data_boundary
        given set_uart_data(0)
        then get_uart_data() == 0
        given set_uart_data(255)
        then get_uart_data() == 255

    invariant system_ready_when_not_processing
        given busy = system_busy()
        and   ready = system_ready()
        assert busy == false implies ready == true

    invariant system_error_implies_not_busy
        given error = system_error()
        and   busy = system_busy()
        assert error == true implies busy == false

    invariant system_ready_implies_mac_uart_ready
        given ready = system_ready()
        assert ready == true implies system_state.mac_ready == true

    bench system_ready_latency
        measure: nanoseconds to system_ready()
        target: < 20ns

    bench system_reset_latency
        measure: nanoseconds to system_reset()
        target: < 100ns
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/isa/ternary_search.t27
// Ternary Search Operations Specification
// Ring 081 - Search algorithms for ternary data
// 01 + 1/23 = 3 | TRINITY

module TernarySearch {
    use base::types;

    const TRIT_NEG : i32 = -1;
    const TRIT_ZERO : i32 = 0;
    const TRIT_POS : i32 = 1;

    // linear_search: O(n) scan, returns index or -1
    fn linear_search(data: []i32, target: i32) i64 {
        var i : usize = 0;
        while (i < data.len) {
            if (data[i] == target) {
                return i as i64;
            }
            i = i + 1;
        }
        return -1;
    }

    // binary_search: O(log n) on sorted data, returns index or -1
    fn binary_search(data: []i32, target: i32) i64 {
        var lo : usize = 0;
        var hi : usize = data.len;
        while (lo < hi) {
            var mid : usize = lo + (hi - lo) / 2;
            if (data[mid] == target) {
                return mid as i64;
            } else if (data[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return -1;
    }

    // ternary_search_min: O(log3 n) find minimum in unimodal array
    fn ternary_search_min(data: []i32) i64 {
        if (data.len == 0) { return -1; }
        var lo : usize = 0;
        var hi : usize = data.len - 1;
        while (hi - lo > 2) {
            var third : usize = (hi - lo) / 3;
            var m1 : usize = lo + third;
            var m2 : usize = hi - third;
            if (data[m1] < data[m2]) {
                hi = m2 - 1;
            } else {
                lo = m1 + 1;
            }
        }
        var best : usize = lo;
        var i : usize = lo + 1;
        while (i <= hi) {
            if (data[i] < data[best]) {
                best = i;
            }
            i = i + 1;
        }
        return best as i64;
    }

    // count_occurrences: Count how many times target appears
    fn count_occurrences(data: []i32, target: i32) usize {
        var count : usize = 0;
        var i : usize = 0;
        while (i < data.len) {
            if (data[i] == target) {
                count = count + 1;
            }
            i = i + 1;
        }
        return count;
    }

    // find_min: Return minimum value in array
    fn find_min(data: []i32) i32 {
        if (data.len == 0) { return TRIT_ZERO; }
        var min_val : i32 = data[0];
        var i : usize = 1;
        while (i < data.len) {
            if (data[i] < min_val) {
                min_val = data[i];
            }
            i = i + 1;
        }
        return min_val;
    }

    // find_max: Return maximum value in array
    fn find_max(data: []i32) i32 {
        if (data.len == 0) { return TRIT_ZERO; }
        var max_val : i32 = data[0];
        var i : usize = 1;
        while (i < data.len) {
            if (data[i] > max_val) {
                max_val = data[i];
            }
            i = i + 1;
        }
        return max_val;
    }

    // test: linear_search finds element
    test linear_search_found {
        var data = [5]i32{ -1, 0, 1, 0, -1 };
        try eq(linear_search(data[0..], TRIT_POS), 2);
    }

    // test: linear_search returns -1 on miss
    test linear_search_miss {
        var data = [3]i32{ -1, 0, -1 };
        try eq(linear_search(data[0..], TRIT_POS), -1);
    }

    // test: binary_search on sorted data
    test binary_search_sorted {
        var data = [5]i32{ -1, -1, 0, 1, 1 };
        try eq(binary_search(data[0..], TRIT_ZERO), 2);
    }

    // test: count_occurrences counts correctly
    test count_occurrences {
        var data = [6]i32{ -1, 0, -1, 1, 0, -1 };
        try eq(count_occurrences(data[0..], TRIT_NEG), 3);
    }

    // test: find_min_max
    test find_min_max {
        var data = [4]i32{ 1, -1, 0, 1 };
        try eq(find_min(data[0..]), TRIT_NEG);
        try eq(find_max(data[0..]), TRIT_POS);
    }

    // invariant: linear_search result matches manual scan
    invariant linear_matches_scan {
        var data = [4]i32{ 0, -1, 1, 0 };
        var idx = linear_search(data[0..], TRIT_NEG);
        idx == 1;
    }

    // invariant: count_occurrences non-negative
    invariant count_nonneg {
        var data = [3]i32{ -1, 0, 1 };
        count_occurrences(data[0..], TRIT_POS) >= 0;
    }

    // bench: binary_search 81 elements
    bench binary_search_81 {
        var data : [81]i32;
        var i : usize = 0;
        while (i < 81) {
            data[i] = (i as i32) % 3 - 1;
            i = i + 1;
        }
        binary_search(data[0..], TRIT_ZERO);
    }
}

