    var spi_done : bool = false;
    var spi_rx_data : u32 = 0;
    var spi_busy : bool = false;

    var test_passed : u32 = 0;
    var test_failed : u32 = 0;
    var bit_count : u32 = 0;

    fn tick() {
        clk = false;
        clk = true;
    }

    fn reset() {
        rst_n = false;
        tick();
        tick();
        rst_n = true;
        tick();
    }

    fn spi_transfer(tx_data : u32) -> u32 {
        spi_start = true;
        spi_mosi_data = tx_data;
        tick();
        spi_start = false;
        var timeout : u32 = 0;
        while !spi_done {
            tick();
            timeout = timeout + 1;
            if timeout > SIM_TIMEOUT {
                return 0xDEAD;
            }
        }
        return spi_rx_data;
    }

    test test_idle_state {
        reset();
        invariant spi_cs_n == true;
        invariant spi_sclk == false;
        invariant spi_busy == false;
    }

    test test_single_transfer {
        reset();
        var rx : u32 = spi_transfer(0xA5);
        invariant spi_done == true;
        invariant spi_busy == false;
        invariant spi_cs_n == true;
    }

    test test_cs_assert_during_transfer {
        reset();
        spi_start = true;
        spi_mosi_data = 0xFF;
        tick();
        invariant spi_busy == true;
        invariant spi_cs_n == false;
        spi_start = false;
    }

    test test_consecutive_transfers {
        reset();
        var rx1 : u32 = spi_transfer(0x01);
        var rx2 : u32 = spi_transfer(0x02);
        var rx3 : u32 = spi_transfer(0x03);
        invariant spi_done == true;
    }

    test test_full_duplex {
        reset();
        spi_miso = true;
        var rx : u32 = spi_transfer(0xAA);
        invariant rx != 0xDEAD;
    }

    test test_zero_data_transfer {
        reset();
        var rx : u32 = spi_transfer(0x00);
        invariant spi_done == true;
    }

    test test_max_data_transfer {
        reset();
        var rx : u32 = spi_transfer(0xFFFFFFFF);
        invariant spi_done == true;
    }

    invariant clk_div_positive : SPI_CLK_DIV > 0;
    invariant cs_high_when_idle : true;

    bench bench_spi_throughput {
        reset();
        var i : u32 = 0;
        while i < 100 {
            spi_transfer(i);
            i = i + 1;
        }
    }
}

