};

/// Agent capability enum
pub const AgentCapability = enum(u8) {
    chat = 0,
    code_edit = 1,
    file_operation = 2,
    web_search = 3,
    execute = 4,
};

// ============================================================================
// Types
// ============================================================================

/// Provider configuration
pub const ProviderConfig = struct {
    name : ProviderType,
    api_key : []u8,
    base_url : []u8,
    model : []u8,
    max_tokens : u32,
    timeout_sec : u16,
    temperature : f64,
};

/// Agent configuration
pub const AgentConfig = struct {
    name : []u8,
    description : []u8,
    capabilities : []AgentCapability,
    system_prompt : []u8,
    model_override : ?[]u8,
    enabled : bool,
};

/// MCP server configuration
pub const MCPServerConfig = struct {
    name : []u8,
    command : []u8,
    args : [][]u8,
    timeout_sec : u16,
    enabled : bool,
};

/// LSP configuration
pub const LSPConfig = struct {
    enabled : bool,
    language_servers : []LanguageServer,
    workspace_roots : []u8,
    initialization_options : []u8,
    timeout_sec : u16,
};

/// Language server configuration
pub const LanguageServer = struct {
    language : []u8,  // e.g., "t27", "zig", "python"
    command : []u8,
    args : [][]u8,
    workspace_root : ?[]u8,
};

/// TUI configuration
pub const TuiConfig = struct {
    theme : []u8,
    keybindings : []Keybinding,
    mouse_enabled : bool,
    confirm_dangerous : bool,
    timeout_ms : u32,
};

/// Keybinding definition
pub const Keybinding = struct {
    name : []u8,
    keys : []u8,
    action : []u8,
};

/// Logging configuration
pub const LoggingConfig = struct {
    level : []u8,  // "debug", "info", "warn", "error"
    file : ?[]u8,  // File path, null for stdout
    format : []u8,  // "json", "text"
    max_size_mb : u16,
};

/// File paths configuration
pub const PathsConfig = struct {
    config_dir : []u8,
    data_dir : []u8,
    cache_dir : []u8,
    log_dir : []u8,
};

/// Main configuration structure
pub const Config = struct {
