    provider : ProviderConfig,
    agents : []AgentConfig,
    mcp_servers : []MCPServerConfig,
    lsp : LSPConfig,
    tui : TuiConfig,
    logging : LoggingConfig,
    paths : PathsConfig,
};

/// Config validation result
pub const ValidationResult = struct {
    valid : bool,
    errors : []ConfigError,
};

/// Configuration error
pub const ConfigError = struct {
    field : []u8,
    message : []u8,
    severity : []u8,
};

// ============================================================================
// Functions
// ============================================================================

/// Create default provider config
pub fn provider_default() ProviderConfig {
    return ProviderConfig{
        .name = .anthropic,
        .api_key = "",
        .base_url = "",
        .model = DEFAULT_MODEL,
        .max_tokens = DEFAULT_MAX_TOKENS,
        .timeout_sec = DEFAULT_TIMEOUT_SEC,
        .temperature = DEFAULT_TEMPERATURE,
    };
}

/// Create provider with API key
pub fn provider_with_key(api_key: []u8) ProviderConfig {
    const base = provider_default();
    return ProviderConfig{ .api_key = api_key, .base_url = base.base_url, .model = base.model, .max_tokens = base.max_tokens, .timeout_sec = base.timeout_sec, .temperature = base.temperature };
}

/// Create default agent config
pub fn agent_default(name: []u8) AgentConfig {
    return AgentConfig{
        .name = name,
        .description = "",
        .capabilities = &[_]AgentCapability{.chat},
        .system_prompt = "",
        .model_override = null,
        .enabled = true,
    };
}

/// Create agent with capabilities
pub fn agent_with_capabilities(name: []u8, capabilities: []AgentCapability) AgentConfig {
    const base = agent_default(name);
    return AgentConfig{ .name = base.name, .description = base.description, .capabilities = capabilities, .system_prompt = base.system_prompt, .model_override = base.model_override, .enabled = base.enabled };
}

/// Create LSP server config
pub fn lsp_server_create(language: []u8, command: []u8, args: [][]u8) LanguageServer {
    return LanguageServer{
        .language = language,
        .command = command,
        .args = args,
        .workspace_root = null,
    };
}

/// Create default TUI config
pub fn tui_default() TuiConfig {
    return TuiConfig{
        .theme = "dark",
        .keybindings = &[_]Keybinding{},
        .mouse_enabled = true,
        .confirm_dangerous = true,
        .timeout_ms = 5000,
    };
}

/// Create default logging config
pub fn logging_default() LoggingConfig {
    return LoggingConfig{
        .level = "info",
        .file = null,
        .format = "text",
        .max_size_mb = 100,
    };
}

/// Create default paths config
pub fn paths_default() PathsConfig {
    return PathsConfig{
        .config_dir = "",
        .data_dir = "",
        .cache_dir = "",
        .log_dir = "",
    };
}

/// Create default config
pub fn config_default() Config {
    return Config{
        .version = 1,
        .provider = provider_default(),
        .agents = &[_]AgentConfig{},
        .mcp_servers = &[_]MCPServerConfig{},
        .lsp = LSPConfig{ .enabled = false, .language_servers = &[_]LanguageServer{}, .workspace_roots = &[_]u8{}, .initialization_options = &[_]u8{}, .timeout_sec = 30 },
        .tui = tui_default(),
        .logging = logging_default(),
        .paths = paths_default(),
    };
}

/// Create validation result with success
pub fn validation_success() ValidationResult {
    return ValidationResult{
        .valid = true,
        .errors = &[_]ConfigError{},
    };
}

/// Create validation result with errors
pub fn validation_failure(errors: []ConfigError) ValidationResult {
    return ValidationResult{
        .valid = false,
        .errors = errors,
    };
}

/// Create config error
pub fn error_create(field: []u8, message: []u8) ConfigError {
    return ConfigError{
        .field = field,
        .message = message,
        .severity = "error",
    };
}

/// Create config error with severity
pub fn error_with_severity(field: []u8, message: []u8, severity: []u8) ConfigError {
    return ConfigError{
        .field = field,
        .message = message,
        .severity = severity,
    };
}

/// Check if provider is Anthropic
pub fn is_anthropic(provider: ProviderConfig) bool {
    return provider.name == .anthropic;
}

/// Check if provider is OpenAI
pub fn is_openai(provider: ProviderConfig) bool {
    return provider.name == .openai;
}

/// Check if provider is custom
pub fn is_custom(provider: ProviderConfig) bool {
    return provider.name == .custom;
}

/// Check if API key is present
pub fn has_api_key(provider: ProviderConfig) bool {
    return provider.api_key.len > 0;
}

/// Check if agent has capability
pub fn agent_has_capability(agent: AgentConfig, capability: AgentCapability) bool {
    for (agent.capabilities) |cap| {
        if (cap == capability) {
            return true;
        }
    }
    return false;
}

/// Check if LSP is enabled
pub fn lsp_is_enabled(config: Config) bool {
    return config.lsp.enabled;
}

/// Add agent to config
pub fn config_add_agent(config: *Config, agent: AgentConfig) void {
    config.agents = append_agents(config.agents, agent);
}

/// Remove agent from config
pub fn config_remove_agent(config: *Config, index: usize) void {
    // Remove at index (simplified)
}

/// Get agent count
pub fn config_agent_count(config: Config) usize {
    return config.agents.len;
}

/// Append agents to slice
pub fn append_agents(slice: []AgentConfig, item: AgentConfig) []AgentConfig {
    var result : []AgentConfig = slice;
    var new_slice : []AgentConfig = &[_]AgentConfig{item};
    for (result) |_| {
        new_slice = append_agents_slice(new_slice, _);
    }
    return new_slice;
}

/// Append agents slice
pub fn append_agents_slice(slice: []AgentConfig, item: AgentConfig) []AgentConfig {
    var result : []AgentConfig = slice;
    result = concat_agents(result, item);
    return result;
}

/// Concatenate agents
pub fn concat_agents(a: []AgentConfig, b: AgentConfig) []AgentConfig {
    var result : []AgentConfig = a;
    var new_slice : []AgentConfig = &[_]AgentConfig{b};
    for (result) |_| {
        new_slice = append_agents_slice(new_slice, _);
    }
    return new_slice;
}

/// Concat byte to string
pub fn concat_string(a: []u8, b: []u8) []u8 {
    var result : []u8 = a;
    for (b) |byte| {
        result = append_byte(result, byte);
    }
    return result;
}

/// Append byte to string
pub fn append_byte(slice: []u8, byte: u8) []u8 {
    var result : []u8 = slice;
    result = concat_string(result, &[_]u8{byte});
    return result;
}

