// SPDX-License-Identifier: Apache-2.0
; fp8_e5m2.t27 — FP8 E5M2 8-bit Floating Point
; 8-bit float with 5 exponent, 2 mantissa bits (with implicit leading bit)
; OCP FP8 format optimized for inference and wide dynamic range
; Range: ~-57k to ~57k, precision: ~3-4 significant bits
; φ² + 1/φ² = 3 | TRINITY

module triformat-fp8_e5m2;

// ============================================================================
// Constants
// ============================================================================

pub const BITS : u8 = 8;
pub const SIGN_BITS : u8 = 1;
pub const EXP_BITS : u8 = 5;
pub const MANT_BITS : u8 = 2;

pub const SIGN_SHIFT : u8 = 7;
pub const EXP_SHIFT : u8 = 2;
pub const MANT_SHIFT : u8 = 0;

pub const SIGN_MASK : u8 = 0x80;    // 1 << 7
pub const EXP_MASK : u8 = 0x7C;     // 0b01111100
pub const MANT_MASK : u8 = 0x03;     // 0b00000011

pub const EXP_MAX : u8 = 31;         // All ones in 5 bits
pub const EXP_MIN : u8 = 0;
pub const EXP_BIAS : u8 = 15;        // Exponent bias for FP8 E5M2

pub const MANT_DIVISOR : u8 = 4;     // 2^2

// FP8 E5M2 special values
pub const FP8_ZERO_POS : u8 = 0x00;
pub const FP8_ZERO_NEG : u8 = 0x80;
pub const FP8_NAN_POS : u8 = 0x7F;   // All exp + mant != 0
pub const FP8_NAN_NEG : u8 = 0xFF;
pub const FP8_INF_POS : u8 = 0x7C;   // All exp + mant = 0
pub const FP8_INF_NEG : u8 = 0xFC;

// Subnormal exponent
pub const SUBNORMAL_EXP : u8 = 0;

// ============================================================================
// Types
// ============================================================================

pub const FP8E5M2 = u8;  // 8-bit value

// ============================================================================
// Extract Functions
// ============================================================================

// fp8_extract_sign(fp8: FP8E5M2) -> i8
// Extract sign bit (bit 7)
// Returns: 0 for positive, -1 for negative
pub fn fp8_extract_sign(fp8: FP8E5M2) i8 {
    const bit = (fp8 >> SIGN_SHIFT) & 1;
    return if (bit != 0) -1 else 0;
}

// fp8_extract_exponent(fp8: FP8E5M2) -> u8
// Extract exponent bits (bits 6-2)
// Returns: 0-31
pub fn fp8_extract_exponent(fp8: FP8E5M2) u8 {
    return (fp8 >> EXP_SHIFT) & 0x1F;
}

// fp8_extract_mantissa(fp8: FP8E5M2) -> u8
// Extract mantissa bits (bits 1-0)
// Returns: 0-3
pub fn fp8_extract_mantissa(fp8: FP8E5M2) u8 {
    return fp8 & MANT_MASK;
}

// fp8_from_components(sign: i8, exp: u8, mant: u8) -> FP8E5M2
// Assemble FP8 from sign, exponent, mantissa
pub fn fp8_from_components(sign: i8, exp: u8, mant: u8) FP8E5M2 {
    const sign_bit = if (sign < 0) 1 else 0;
    return (@as(FP8E5M2, @intCast(sign_bit)) << SIGN_SHIFT) |
           (@as(FP8E5M2, @intCast(exp & 0x1F)) << EXP_SHIFT) |
           (mant & MANT_MASK);
}

// ============================================================================
// Special Value Checks
// ============================================================================

// fp8_is_zero(fp8: FP8E5M2) -> bool
// Check if FP8 is zero (positive or negative)
pub fn fp8_is_zero(fp8: FP8E5M2) bool {
    return fp8 == FP8_ZERO_POS or fp8 == FP8_ZERO_NEG;
}

// fp8_is_special(fp8: FP8E5M2) -> bool
// Check if FP8 is Inf or NaN (exp == 31)
pub fn fp8_is_special(fp8: FP8E5M2) bool {
    return fp8_extract_exponent(fp8) == EXP_MAX;
}

// fp8_is_inf(fp8: FP8E5M2) -> bool
// Check if FP8 is infinity (exp == 31, mant == 0)
pub fn fp8_is_inf(fp8: FP8E5M2) bool {
    return fp8_extract_exponent(fp8) == EXP_MAX and fp8_extract_mantissa(fp8) == 0;
}

// fp8_is_nan(fp8: FP8E5M2) -> bool
// Check if FP8 is NaN (exp == 31, mant != 0)
pub fn fp8_is_nan(fp8: FP8E5M2) bool {
    return fp8_extract_exponent(fp8) == EXP_MAX and fp8_extract_mantissa(fp8) != 0;
}

// fp8_is_subnormal(fp8: FP8E5M2) -> bool
// Check if FP8 is subnormal (exp == 0, mant != 0)
pub fn fp8_is_subnormal(fp8: FP8E5M2) bool {
    return fp8_extract_exponent(fp8) == 0 and fp8_extract_mantissa(fp8) != 0;
}

// ============================================================================
// Encode/Decode Functions
// ============================================================================

// fp8_encode_f32(value: f32) -> FP8E5M2
// Encode IEEE 754 single precision to FP8 E5M2
// Round-to-nearest, ties to even
pub fn fp8_encode_f32(value: f32) FP8E5M2 {
    // Handle zero
    if (value == 0.0) {
        return if (std.math.signbit(value)) FP8_ZERO_NEG else FP8_ZERO_POS;
    }

    // Handle NaN
    if (std.math.isNan(value)) {
        return if (value < 0.0) FP8_NAN_NEG else FP8_NAN_POS;
    }

    // Handle Infinity
    if (std.math.isInf(value)) {
        return if (value < 0.0) FP8_INF_NEG else FP8_INF_POS;
    }

    // Extract sign
    const sign = if (value < 0.0) -1 else 0;
    const abs_value = if (value < 0.0) -value else value;

    // Get f32 components
    const f32_bits: u32 = @bitCast(abs_value);
    var f32_exp: i16 = @as(i16, @intCast((f32_bits >> 23) & 0xFF)) - 127;
    var f32_mant: u32 = f32_bits & 0x007FFFFF;

    // Handle very small values (subnormals)
    if (f32_exp <= @as(i16, -EXP_BIAS)) {
        // Below FP8 minimum normal - try to encode as subnormal
        const subnormal_shift = @as(i16, -EXP_BIAS) - f32_exp + 1;
        if (subnormal_shift > 2 + 23) {
            return if (sign < 0) FP8_ZERO_NEG else FP8_ZERO_POS;
        }
        var mant = f32_mant >> 23;
        if (subnormal_shift > 0) {
            const shift_amount = @as(u5, @intCast(subnormal_shift));
            if (shift_amount <= 24) {
                mant = (f32_mant | 0x00800000) >> shift_amount;
            }
        }
        return fp8_from_components(sign, 0, @as(u8, @truncate(mant)) & 0x03);
    }

    // Convert exp from f32 bias (127) to FP8 bias (15)
    var fp8_exp = @as(i16, f32_exp + EXP_BIAS);

    // Clamp exponent
    if (fp8_exp >= EXP_MAX) {
        return if (sign < 0) FP8_INF_NEG else FP8_INF_POS;
    } else if (fp8_exp < 1) {
        // Underflow to zero (could be subnormal, simplified)
        return if (sign < 0) FP8_ZERO_NEG else FP8_ZERO_POS;
    }

    // Extract mantissa and scale to 2 bits
    // f32 mantissa is 24 bits (including implicit 1), FP8 needs 2 bits
    // Shift right by 22 bits (24 - 2 = 22)
    var mant = f32_mant >> 22;

    // Round-to-nearest with ties to even
    const discarded = f32_mant & 0x003FFFFF;  // Lower 22 bits
    if ((discarded & 0x00200000) != 0) {
        // Halfway or more
        if ((discarded & 0x001FFFFF) != 0 or (mant & 1) != 0) {
            mant += 1;
            if (mant > MANT_MASK) {
                mant = 0;
                if (fp8_exp < @as(i16, EXP_MAX - 1)) {
                    fp8_exp += 1;
                }
            }
        }
    }

    return fp8_from_components(sign, @as(u8, @intCast(fp8_exp)), @as(u8, mant));
}

// fp8_decode_f32(fp8: FP8E5M2) -> f32
// Decode FP8 E5M2 to IEEE 754 single precision
pub fn fp8_decode_f32(fp8: FP8E5M2) f32 {
    // Handle zero
    if (fp8_is_zero(fp8)) {
        return if (fp8_extract_sign(fp8) < 0) -0.0 else 0.0;
    }

    // Handle NaN
    if (fp8_is_nan(fp8)) {
        return std.math.nan(f32);
    }

    // Handle Infinity
    if (fp8_is_inf(fp8)) {
        return if (fp8_extract_sign(fp8) < 0) -std.math.inf(f32) else std.math.inf(f32);
    }

    // Extract components
    const sign = fp8_extract_sign(fp8);
    const exp = fp8_extract_exponent(fp8);
    const mant = fp8_extract_mantissa(fp8);

    var f32_value: f32 = undefined;

    // Handle subnormal
    if (exp == 0) {
        // Subnormal: value = mant * 2^(-14) = mant * 2^(1-bias)
        const bias_adjusted: i8 = 1 - @as(i8, EXP_BIAS);
        const mant_f32 = @as(f32, @floatFromInt(mant)) / @as(f32, @floatFromInt(MANT_DIVISOR));
        f32_value = mant_f32 * std.math.pow(f32, 2.0, @as(f32, @floatFromInt(bias_adjusted)));
    } else {
        // Normal: value = (1 + mant/4) * 2^(exp - 15)
        const bias_adjusted = @as(i16, exp) - @as(i16, EXP_BIAS);
        const mant_f32 = 1.0 + (@as(f32, @floatFromInt(mant)) / @as(f32, @floatFromInt(MANT_DIVISOR)));
        f32_value = mant_f32 * std.math.pow(f32, 2.0, @as(f32, @floatFromInt(bias_adjusted)));
    }

    return if (sign < 0) -f32_value else f32_value;
}

// fp8_encode_f64(value: f64) -> FP8E5M2
// Encode IEEE 754 double precision to FP8 E5M2
pub fn fp8_encode_f64(value: f64) FP8E5M2 {
    return fp8_encode_f32(@as(f32, @floatCast(value)));
}

// fp8_decode_f64(fp8: FP8E5M2) -> f64
// Decode FP8 E5M2 to IEEE 754 double precision
pub fn fp8_decode_f64(fp8: FP8E5M2) f64 {
    const f32_val = fp8_decode_f32(fp8);
    return @as(f64, @floatFromInt(f32_val));
}

// ============================================================================
// Arithmetic Operations
// ============================================================================

// fp8_add(a: FP8E5M2, b: FP8E5M2) -> FP8E5M2
// Add two FP8 values
pub fn fp8_add(a: FP8E5M2, b: FP8E5M2) FP8E5M2 {
    const fa = fp8_decode_f32(a);
    const fb = fp8_decode_f32(b);
    return fp8_encode_f32(fa + fb);
}

// fp8_sub(a: FP8E5M2, b: FP8E5M2) -> FP8E5M2
// Subtract two FP8 values
pub fn fp8_sub(a: FP8E5M2, b: FP8E5M2) FP8E5M2 {
    const fa = fp8_decode_f32(a);
    const fb = fp8_decode_f32(b);
    return fp8_encode_f32(fa - fb);
}

// fp8_mul(a: FP8E5M2, b: FP8E5M2) -> FP8E5M2
// Multiply two FP8 values
pub fn fp8_mul(a: FP8E5M2, b: FP8E5M2) FP8E5M2 {
    const fa = fp8_decode_f32(a);
    const fb = fp8_decode_f32(b);
    return fp8_encode_f32(fa * fb);
}

// fp8_div(a: FP8E5M2, b: FP8E5M2) -> FP8E5M2
// Divide two FP8 values
pub fn fp8_div(a: FP8E5M2, b: FP8E5M2) FP8E5M2 {
    const fb = fp8_decode_f32(b);
    if (fb == 0.0) {
        const fa = fp8_decode_f32(a);
        return if (fa < 0.0) FP8_INF_NEG else FP8_INF_POS;
    }
    const fa = fp8_decode_f32(a);
    return fp8_encode_f32(fa / fb);
}

// fp8_sqrt(value: FP8E5M2) -> FP8E5M2
// Square root of FP8 value
pub fn fp8_sqrt(value: FP8E5M2) FP8E5M2 {
    const fv = fp8_decode_f32(value);
    if (fv < 0.0) {
        return FP8_NAN_POS;
    }
    return fp8_encode_f32(std.math.sqrt(fv));
}

// fp8_rsqrt(value: FP8E5M2) -> FP8E5M2
// Reciprocal square root (1/sqrt(x))
pub fn fp8_rsqrt(value: FP8E5M2) FP8E5M2 {
    const fv = fp8_decode_f32(value);
    if (fv <= 0.0) {
        return FP8_INF_POS;
    }
    return fp8_encode_f32(1.0 / std.math.sqrt(fv));
}

// fp8_abs(value: FP8E5M2) -> FP8E5M2
// Absolute value of FP8
pub fn fp8_abs(value: FP8E5M2) FP8E5M2 {
    return value & ~SIGN_MASK;
}

// fp8_neg(value: FP8E5M2) -> FP8E5M2
// Negate FP8
pub fn fp8_neg(value: FP8E5M2) FP8E5M2 {
    return value ^ SIGN_MASK;
}

// fp8_is_equal(a: FP8E5M2, b: FP8E5M2) -> bool
// Check if two FP8 values are equal
pub fn fp8_is_equal(a: FP8E5M2, b: FP8E5M2) bool {
    if (fp8_is_nan(a) or fp8_is_nan(b)) {
        return false;
    }
    if (fp8_is_zero(a) and fp8_is_zero(b)) {
        return true;
    }
    return a == b;
}

// fp8_is_greater(a: FP8E5M2, b: FP8E5M2) -> bool
// Check if a > b
pub fn fp8_is_greater(a: FP8E5M2, b: FP8E5M2) bool {
    if (fp8_is_nan(a) or fp8_is_nan(b)) {
        return false;
    }
    const sign_a = fp8_extract_sign(a);
    const sign_b = fp8_extract_sign(b);
    if (sign_a != sign_b) {
        return sign_a > sign_b;
    }
    if (sign_a < 0) {
        return fp8_neg(a) > fp8_neg(b);
    }
    return a > b;
}

// fp8_max(a: FP8E5M2, b: FP8E5M2) -> FP8E5M2
// Return the larger of two FP8 values
pub fn fp8_max(a: FP8E5M2, b: FP8E5M2) FP8E5M2 {
    return if (fp8_is_greater(a, b)) a else b;
}

// fp8_min(a: FP8E5M2, b: FP8E5M2) -> FP8E5M2
// Return the smaller of two FP8 values
pub fn fp8_min(a: FP8E5M2, b: FP8E5M2) FP8E5M2 {
    return if (fp8_is_greater(a, b)) b else a;
}

// fp8_clamp(value: FP8E5M2, min: FP8E5M2, max: FP8E5M2) -> FP8E5M2
// Clamp value between min and max
pub fn fp8_clamp(value: FP8E5M2, min: FP8E5M2, max: FP8E5M2) FP8E5M2 {
    return fp8_min(fp8_max(value, min), max);
}

// fp8_lerp(a: FP8E5M2, b: FP8E5M2, t: f32) -> FP8E5M2
// Linear interpolation between a and b
pub fn fp8_lerp(a: FP8E5M2, b: FP8E5M2, t: f32) FP8E5M2 {
    const fa = fp8_decode_f32(a);
    const fb = fp8_decode_f32(b);
    const result = fa + (fb - fa) * t;
    return fp8_encode_f32(result);
}

// fp8_fma(a: FP8E5M2, b: FP8E5M2, c: FP8E5M2) -> FP8E5M2
// Fused multiply-add: a * b + c
pub fn fp8_fma(a: FP8E5M2, b: FP8E5M2, c: FP8E5M2) FP8E5M2 {
    const fa = fp8_decode_f32(a);
    const fb = fp8_decode_f32(b);
    const fc = fp8_decode_f32(c);
    return fp8_encode_f32(fa * fb + fc);
}

// fp8_scale(value: FP8E5M2, scale: f32) -> FP8E5M2
// Scale FP8 value by scalar
pub fn fp8_scale(value: FP8E5M2, scale: f32) FP8E5M2 {
    const fv = fp8_decode_f32(value);
    return fp8_encode_f32(fv * scale);
}

// fp8_relu(value: FP8E5M2) -> FP8E5M2
// ReLU activation: max(0, x)
pub fn fp8_relu(value: FP8E5M2) FP8E5M2 {
    return if (fp8_extract_sign(value) < 0) FP8_ZERO_POS else value;
}

// fp8_sigmoid(value: FP8E5M2) -> FP8E5M2
// Sigmoid activation: 1 / (1 + e^(-x))
pub fn fp8_sigmoid(value: FP8E5M2) FP8E5M2 {
    const fv = fp8_decode_f32(value);
    return fp8_encode_f32(1.0 / (1.0 + std.math.exp(-fv)));
}

// fp8_tanh(value: FP8E5M2) -> FP8E5M2
// Tanh activation
pub fn fp8_tanh(value: FP8E5M2) FP8E5M2 {
    const fv = fp8_decode_f32(value);
    return fp8_encode_f32(std.math.tanh(fv));
}

// fp8_gelu(value: FP8E5M2) -> FP8E5M2
// GELU activation
pub fn fp8_gelu(value: FP8E5M2) FP8E5M2 {
    const fv = fp8_decode_f32(value);
    const sqrt_2_over_pi = 0.7978845608;
    const cube_coeff = 0.044715;
    const tanh_arg = fv * (1.0 + cube_coeff * fv * fv);
    return fp8_encode_f32(0.5 * fv * (1.0 + std.math.tanh(sqrt_2_over_pi * tanh_arg)));
}

// fp8_swish(value: FP8E5M2) -> FP8E5M2
// Swish activation: x * sigmoid(x)
pub fn fp8_swish(value: FP8E5M2) FP8E5M2 {
    const fv = fp8_decode_f32(value);
    return fp8_encode_f32(fv * (1.0 / (1.0 + std.math.exp(-fv))));
}

// fp8_quantize_to_int4(value: FP8E5M2) -> i8
// Quantize FP8 to Int4 (range [-8, 7])
pub fn fp8_quantize_to_int4(value: FP8E5M2) i8 {
    const fv = fp8_decode_f32(value);
    // E5M2 has wider range, so scale differently
    const max_range: f32 = 240.0;
    const scaled = (fv / max_range) * 7.0;
    var result: i32 = @intFromFloat(@round(scaled));
    if (result > 7) {
        result = 7;
    } else if (result < -8) {
        result = -8;
    }
    return @as(i8, @intCast(result));
}

// fp8_quantize_to_int8(value: FP8E5M2) -> i8
// Quantize FP8 to Int8 (range [-128, 127])
pub fn fp8_quantize_to_int8(value: FP8E5M2) i8 {
    const fv = fp8_decode_f32(value);
    // E5M2 has wider range, so scale differently
    const max_range: f32 = 240.0;
    const scaled = (fv / max_range) * 127.0;
    var result: i32 = @intFromFloat(@round(scaled));
    if (result > 127) {
        result = 127;
    } else if (result < -128) {
        result = -128;
    }
    return @as(i8, @intCast(result));
}

// fp8_from_f32_scaled(value: f32, scale: f32) -> FP8E5M2
// Encode f32 to FP8 with custom scale factor
// Useful for quantization with specific dynamic range
pub fn fp8_from_f32_scaled(value: f32, scale: f32) FP8E5M2 {
    return fp8_encode_f32(value * scale);
}

// fp8_to_f32_scaled(value: FP8E5M2, scale: f32) -> f32
// Decode FP8 to f32 with custom scale factor
pub fn fp8_to_f32_scaled(value: FP8E5M2, scale: f32) f32 {
    return fp8_decode_f32(value) / scale;
}

// fp8_dot_product(a: []const FP8E5M2, b: []const FP8E5M2) -> FP8E5M2
// Dot product of two FP8 arrays (fixed size 8 for example)
// Returns accumulated FP8 value
pub fn fp8_dot_product(a: []const FP8E5M2, b: []const FP8E5M2) FP8E5M2 {
    var sum: f32 = 0.0;
    for (a, 0..) |val_a, i| {
        if (i >= b.len) break;
        const fa = fp8_decode_f32(val_a);
        const fb = fp8_decode_f32(b[i]);
        sum += fa * fb;
    }
    return fp8_encode_f32(sum);
}

// fp8_vector_add(a: []const FP8E5M2, b: []const FP8E5M2, result: []FP8E5M2) -> void
// Vector addition: result[i] = a[i] + b[i]
pub fn fp8_vector_add(a: []const FP8E5M2, b: []const FP8E5M2, result: []FP8E5M2) void {
    const len = @min(a.len, b.len);
    for (0..len) |i| {
        result[i] = fp8_add(a[i], b[i]);
    }
}

// fp8_vector_scale(vec: []const FP8E5M2, scale: FP8E5M2, result: []FP8E5M2) -> void
// Vector scale: result[i] = vec[i] * scale
pub fn fp8_vector_scale(vec: []const FP8E5M2, scale: FP8E5M2, result: []FP8E5M2) void {
    const scale_f = fp8_decode_f32(scale);
    for (vec, 0..) |val, i| {
        result[i] = fp8_encode_f32(fp8_decode_f32(val) * scale_f);
    }
}

// fp8_vector_sum(vec: []const FP8E5M2) -> FP8E5M2
// Sum all elements of a vector
pub fn fp8_vector_sum(vec: []const FP8E5M2) FP8E5M2 {
    var sum: f32 = 0.0;
    for (vec) |val| {
        sum += fp8_decode_f32(val);
    }
    return fp8_encode_f32(sum);
}

// fp8_vector_mean(vec: []const FP8E5M2) -> FP8E5M2
// Mean of all elements of a vector
pub fn fp8_vector_mean(vec: []const FP8E5M2) FP8E5M2 {
    if (vec.len == 0) {
        return FP8_ZERO_POS;
    }
    const sum = fp8_vector_sum(vec);
    return fp8_div(sum, fp8_from_f32(@as(f32, @floatFromInt(vec.len))));
}

// fp8_softmax(vec: []const FP8E5M2, result: []FP8E5M2) -> void
// Softmax activation: result[i] = exp(vec[i]) / sum(exp(vec))
pub fn fp8_softmax(vec: []const FP8E5M2, result: []FP8E5M2) void {
    // Find max for numerical stability
    var max_val: f32 = -std.math.inf(f32);
    for (vec) |val| {
        const fv = fp8_decode_f32(val);
        if (fv > max_val) {
            max_val = fv;
        }
    }

    // Compute exp values and sum
    var sum_exp: f32 = 0.0;
    for (vec, 0..) |val, i| {
        const fv = fp8_decode_f32(val);
        const exp_val = std.math.exp(fv - max_val);
        result[i] = fp8_encode_f32(exp_val);
        sum_exp += exp_val;
    }

    // Normalize
    const inv_sum = 1.0 / sum_exp;
    for (result, 0..) |val, i| {
        const fv = fp8_decode_f32(val);
        result[i] = fp8_encode_f32(fv * inv_sum);
    }
}

