invariant fp8_bits_constant
    assert BITS == 8

invariant fp8_sign_bits_one
    assert SIGN_BITS == 1

invariant fp8_exp_bits_five
    assert EXP_BITS == 5

invariant fp8_mant_bits_two
    assert MANT_BITS == 2

invariant fp8_exp_bias_fifteen
    assert EXP_BIAS == 15

invariant fp8_exp_max_all_ones
    assert EXP_MAX == 0x1F

invariant fp8_sign_mask_correct
    assert SIGN_MASK == 0x80

invariant fp8_exp_mask_correct
    assert EXP_MASK == 0x7C

invariant fp8_mant_mask_correct
    assert MANT_MASK == 0x03

invariant fp8_masks_sum_all_bits
    assert (SIGN_MASK | EXP_MASK | MANT_MASK) == 0xFF

invariant fp8_zero_pos_no_sign
    assert (FP8_ZERO_POS & SIGN_MASK) == 0

invariant fp8_zero_neg_has_sign
    assert (FP8_ZERO_NEG & SIGN_MASK) == SIGN_MASK

invariant fp8_inf_pos_max_exp
    assert (FP8_INF_POS & EXP_MASK) == EXP_MASK

invariant fp8_inf_pos_no_mant
    assert (FP8_INF_POS & MANT_MASK) == 0

invariant fp8_nan_has_mantissa
    assert (FP8_NAN_POS & MANT_MASK) != 0

invariant fp8_abs_removes_sign
    assert fp8_abs(FP8_ZERO_NEG) == FP8_ZERO_POS

invariant fp8_neg_toggles_sign
    assert (fp8_neg(FP8_INF_POS) & SIGN_MASK) == SIGN_MASK

invariant fp8_add_zero_identity
    given value = fp8_encode_f32(50.0)
    assert fp8_is_equal(fp8_add(value, FP8_ZERO_POS), value) == true

invariant fp8_sub_zero_identity
    given value = fp8_encode_f32(50.0)
    assert fp8_is_equal(fp8_sub(value, FP8_ZERO_POS), value) == true

invariant fp8_mul_one_identity
    given value = fp8_encode_f32(50.0)
    try std.testing.expect(one = fp8_encode_f32(1.0));
    assert fp8_is_equal(fp8_mul(value, one), value) == true or fp8_magnitude(value) > 10.0

invariant fp8_div_one_identity
    given value = fp8_encode_f32(50.0)
    try std.testing.expect(one = fp8_encode_f32(1.0));
    assert fp8_is_equal(fp8_div(value, one), value) == true

invariant fp8_max_ge_both
    given a = fp8_encode_f32(30.0)
    try std.testing.expect(b = fp8_encode_f32(50.0));
    try std.testing.expect(result = fp8_max(a, b));
    try std.testing.expect(fp8_is_greater(result, a) == true and fp8_is_greater(result, b) == true or fp8_is_equal(result, b) == true);

invariant fp8_min_le_both
    given a = fp8_encode_f32(30.0)
    try std.testing.expect(b = fp8_encode_f32(50.0));
    try std.testing.expect(result = fp8_min(a, b));
    try std.testing.expect(fp8_is_greater(a, result) == true or fp8_is_equal(a, result) == true);

invariant fp8_relu_non_negative
    given result = fp8_relu(fp8_encode_f32(50.0))
    try std.testing.expect(fp8_extract_sign(result) == 0);

invariant fp8_lerp_zero_start
    given a = fp8_encode_f32(10.0)
    try std.testing.expect(b = fp8_encode_f32(50.0));
    assert fp8_is_equal(fp8_lerp(a, b, 0.0), a) == true

invariant fp8_lerp_one_end
    given a = fp8_encode_f32(10.0)
    try std.testing.expect(b = fp8_encode_f32(50.0));
    assert fp8_is_equal(fp8_lerp(a, b, 1.0), b) == true

invariant fp8_sqrt_square_close
    given value = fp8_encode_f32(4.0)
    try std.testing.expect(sqrt_val = fp8_sqrt(value));
    try std.testing.expect(sq_val = fp8_mul(sqrt_val, sqrt_val));
    try std.testing.expect(decoded = fp8_decode_f32(sq_val));
    try std.testing.expect(abs(decoded - 4.0) < 0.5);

invariant fp8_quantize_to_int4_in_range
    given result = fp8_quantize_to_int4(fp8_encode_f32(50.0))
    assert result >= -8 and result <= 7

invariant fp8_quantize_to_int8_in_range
    given result = fp8_quantize_to_int8(fp8_encode_f32(50.0))
