    try std.testing.expect(scale = 2.0);
    try std.testing.expect(scaled = fp8_scale(value, scale));
    try std.testing.expect(decoded = fp8_to_f32_scaled(scaled, scale));
    try std.testing.expect(abs(decoded - fp8_decode_f32(value)) < 5.0);

