module fbb-active-path;

// ============================================================================
// Constants
// ============================================================================

pub const FBB_OPCODE_BASE : u8 = 0xD0;  // FBB opcodes start at 0xD0

pub const FBB_OP_PATH_SELECT : u8 = 0x00;
pub const FBB_OP_PATH_ENABLE : u8 = 0x01;
pub const FBB_OP_PATH_DISABLE : u8 = 0x02;
pub const FBB_OP_PATH_STATUS : u8 = 0x03;
pub const FBB_OP_PATH_RESET : u8 = 0x04;
pub const FBB_OP_PATH_BYPASS : u8 = 0x05;
pub const FBB_OP_PATH_LOOPBACK : u8 = 0x06;
pub const FBB_OP_PATH_CONFIG : u8 = 0x07;
pub const FBB_OP_MAX : u8 = 0x08;

pub const FBB_PATH_COUNT : u8 = 8;
pub const FBB_MAX_PATHS : u8 = 8;

pub const FBB_PATH_STATE_DISABLED : u8 = 0;
pub const FBB_PATH_STATE_ENABLED : u8 = 1;
pub const FBB_PATH_STATE_ACTIVE : u8 = 2;
pub const FBB_PATH_STATE_ERROR : u8 = 3;
pub const FBB_PATH_STATE_BYPASSED : u8 = 4;
pub const FBB_PATH_STATE_MAX : u8 = 5;

pub const FBB_LATENCY_MIN_CYCLES : u8 = 1;
pub const FBB_LATENCY_MAX_CYCLES : u8 = 16;
pub const FBB_DEFAULT_LATENCY : u8 = 4;

pub const FBB_BANDWIDTH_MIN_MBPS : u32 = 100;
pub const FBB_BANDWIDTH_MAX_MBPS : u32 = 10000;
pub const FBB_DEFAULT_BANDWIDTH : u32 = 1000;

// ============================================================================
// Types
// ============================================================================

pub const FbbOp = enum(u8) {
    path_select = FBB_OP_PATH_SELECT,
    path_enable = FBB_OP_PATH_ENABLE,
    path_disable = FBB_OP_PATH_DISABLE,
    path_status = FBB_OP_PATH_STATUS,
    path_reset = FBB_OP_PATH_RESET,
    path_bypass = FBB_OP_PATH_BYPASS,
    path_loopback = FBB_OP_PATH_LOOPBACK,
    path_config = FBB_OP_PATH_CONFIG,
}

pub const FbbPathState = enum(u8) {
    disabled = FBB_PATH_STATE_DISABLED,
    enabled = FBB_PATH_STATE_ENABLED,
    active = FBB_PATH_STATE_ACTIVE,
    error = FBB_PATH_STATE_ERROR,
    bypassed = FBB_PATH_STATE_BYPASSED,
}

pub const FbbPathConfig = struct {
    path_index : u8,
    enabled : bool,
    latency_cycles : u8,
    bandwidth_mbps : u32,
    priority : u8,
    auto_bypass : bool,
}

pub const FbbPathStatus = struct {
    path_index : u8,
    state : FbbPathState,
    active : bool,
    error_code : u8,
    throughput_mbps : u32,
    latency_measured : u16,
}

pub const FbbActivePath = struct {
    active_path : u8,
    bypass_path : u8,
    loopback_enabled : bool,
    paths : [FBB_MAX_PATHS]FbbPathStatus,
}

pub const FbbCommand = struct {
    op : FbbOp,
    path_index : u8,
    param1 : u16,
    param2 : u16,
}

// ============================================================================
// Path Config Functions
// ============================================================================

// fbb_path_config_init(index: u8) -> FbbPathConfig
// Initialize path config
pub fn fbb_path_config_init(index: u8) -> FbbPathConfig {
    return FbbPathConfig {
        .path_index = index & 0x07,
        .enabled = false,
        .latency_cycles = FBB_DEFAULT_LATENCY,
        .bandwidth_mbps = FBB_DEFAULT_BANDWIDTH,
        .priority = 4,
        .auto_bypass = false,
    };
}

// fbb_path_config_low_latency(index: u8) -> FbbPathConfig
// Create low latency path config
pub fn fbb_path_config_low_latency(index: u8) -> FbbPathConfig {
    return FbbPathConfig {
        .path_index = index & 0x07,
        .enabled = false,
        .latency_cycles = FBB_LATENCY_MIN_CYCLES,
        .bandwidth_mbps = FBB_DEFAULT_BANDWIDTH,
        .priority = 7,
        .auto_bypass = false,
    };
}

// fbb_path_config_high_bandwidth(index: u8) -> FbbPathConfig
// Create high bandwidth path config
pub fn fbb_path_config_high_bandwidth(index: u8) -> FbbPathConfig {
    return FbbPathConfig {
        .path_index = index & 0x07,
        .enabled = false,
        .latency_cycles = 8,
        .bandwidth_mbps = FBB_BANDWIDTH_MAX_MBPS,
        .priority = 3,
        .auto_bypass = false,
    };
}

// fbb_path_config_enable(config: FbbPathConfig) -> FbbPathConfig
// Enable path in config
pub fn fbb_path_config_enable(config: FbbPathConfig) -> FbbPathConfig {
    return FbbPathConfig {
        .path_index = config.path_index,
        .enabled = true,
        .latency_cycles = config.latency_cycles,
        .bandwidth_mbps = config.bandwidth_mbps,
        .priority = config.priority,
        .auto_bypass = config.auto_bypass,
    };
}

// ============================================================================
// Path Status Functions
// ============================================================================

// fbb_path_status_init(index: u8) -> FbbPathStatus
// Initialize path status
pub fn fbb_path_status_init(index: u8) -> FbbPathStatus {
    return FbbPathStatus {
        .path_index = index & 0x07,
        .state = FbbPathState.disabled,
        .active = false,
        .error_code = 0,
        .throughput_mbps = 0,
        .latency_measured = 0,
    };
}

// fbb_path_status_enable(status: FbbPathStatus) -> FbbPathStatus
// Enable path
pub fn fbb_path_status_enable(status: FbbPathStatus) -> FbbPathStatus {
    return FbbPathStatus {
        .path_index = status.path_index,
        .state = FbbPathState.enabled,
        .active = false,
        .error_code = 0,
        .throughput_mbps = status.throughput_mbps,
        .latency_measured = status.latency_measured,
    };
}

// fbb_path_status_activate(status: FbbPathStatus) -> FbbPathStatus
// Activate path
pub fn fbb_path_status_activate(status: FbbPathStatus) -> FbbPathStatus {
    return FbbPathStatus {
        .path_index = status.path_index,
        .state = FbbPathState.active,
        .active = true,
        .error_code = 0,
        .throughput_mbps = status.throughput_mbps,
        .latency_measured = status.latency_measured,
    };
}

// fbb_path_status_bypass(status: FbbPathStatus) -> FbbPathStatus
// Bypass path
pub fn fbb_path_status_bypass(status: FbbPathStatus) -> FbbPathStatus {
    return FbbPathStatus {
        .path_index = status.path_index,
        .state = FbbPathState.bypassed,
        .active = false,
        .error_code = 0,
        .throughput_mbps = 0,
        .latency_measured = 0,
    };
}

// fbb_path_status_error(status: FbbPathStatus, error_code: u8) -> FbbPathStatus
// Set error status
pub fn fbb_path_status_error(status: FbbPathStatus, error_code: u8) -> FbbPathStatus {
    return FbbPathStatus {
        .path_index = status.path_index,
        .state = FbbPathState.error,
        .active = false,
        .error_code = error_code,
        .throughput_mbps = 0,
        .latency_measured = 0,
    };
}

// fbb_path_status_update_metrics(status: FbbPathStatus, throughput: u32, latency: u16) -> FbbPathStatus
// Update path metrics
pub fn fbb_path_status_update_metrics(status: FbbPathStatus, throughput: u32, latency: u16) -> FbbPathStatus {
    return FbbPathStatus {
        .path_index = status.path_index,
        .state = status.state,
        .active = status.active,
        .error_code = status.error_code,
        .throughput_mbps = throughput,
        .latency_measured = latency,
    };
}

// ============================================================================
// Active Path Functions
// ============================================================================

// fbb_active_path_init() -> FbbActivePath
// Initialize active path
pub fn fbb_active_path_init() -> FbbActivePath {
    var paths : [FBB_MAX_PATHS]FbbPathStatus = undefined;
    for (0..FBB_MAX_PATHS) |i| {
        paths[i] = fbb_path_status_init(@as(u8, @truncate(i)));
    }
    return FbbActivePath {
        .active_path = 0,
        .bypass_path = 0xFF,  // No bypass
        .loopback_enabled = false,
        .paths = paths,
    };
}

// fbb_active_path_select(active: FbbActivePath, path_index: u8) -> FbbActivePath
// Select active path
pub fn fbb_active_path_select(active: FbbActivePath, path_index: u8) -> FbbActivePath {
    const idx = path_index & 0x07;
    var new_paths = active.paths;

    // Deactivate current active path
    new_paths[active.active_path] = fbb_path_status_enable(new_paths[active.active_path]);

    // Activate new path
    new_paths[idx] = fbb_path_status_activate(new_paths[idx]);

    return FbbActivePath {
        .active_path = idx,
        .bypass_path = active.bypass_path,
        .loopback_enabled = active.loopback_enabled,
        .paths = new_paths,
    };
}

// fbb_active_path_enable_bypass(active: FbbActivePath, bypass_index: u8) -> FbbActivePath
// Enable bypass path
pub fn fbb_active_path_enable_bypass(active: FbbActivePath, bypass_index: u8) -> FbbActivePath {
    const idx = bypass_index & 0x07;
    var new_paths = active.paths;
    new_paths[idx] = fbb_path_status_bypass(new_paths[idx]);

    return FbbActivePath {
        .active_path = active.active_path,
        .bypass_path = idx,
        .loopback_enabled = active.loopback_enabled,
        .paths = new_paths,
    };
}

// fbb_active_path_disable_bypass(active: FbbActivePath) -> FbbActivePath
// Disable bypass path
pub fn fbb_active_path_disable_bypass(active: FbbActivePath) -> FbbActivePath {
    var new_paths = active.paths;

    // Restore bypassed path
    if (active.bypass_path != 0xFF) {
        new_paths[active.bypass_path] = fbb_path_status_enable(new_paths[active.bypass_path]);
    }

    return FbbActivePath {
        .active_path = active.active_path,
        .bypass_path = 0xFF,
        .loopback_enabled = active.loopback_enabled,
        .paths = new_paths,
    };
}

// fbb_active_path_enable_loopback(active: FbbActivePath) -> FbbActivePath
// Enable loopback
pub fn fbb_active_path_enable_loopback(active: FbbActivePath) -> FbbActivePath {
    return FbbActivePath {
        .active_path = active.active_path,
        .bypass_path = active.bypass_path,
        .loopback_enabled = true,
        .paths = active.paths,
    };
}

// fbb_active_path_disable_loopback(active: FbbActivePath) -> FbbActivePath
// Disable loopback
pub fn fbb_active_path_disable_loopback(active: FbbActivePath) -> FbbActivePath {
    return FbbActivePath {
        .active_path = active.active_path,
        .bypass_path = active.bypass_path,
        .loopback_enabled = false,
        .paths = active.paths,
    };
}

// fbb_active_path_get_path(active: FbbActivePath, path_index: u8) -> FbbPathStatus
// Get path status
pub fn fbb_active_path_get_path(active: FbbActivePath, path_index: u8) -> FbbPathStatus {
    const idx = path_index & 0x07;
    return active.paths[idx];
}

// fbb_active_path_update_path_metrics(active: FbbActivePath, path_index: u8, throughput: u32, latency: u16) -> FbbActivePath
// Update path metrics
pub fn fbb_active_path_update_path_metrics(active: FbbActivePath, path_index: u8, throughput: u32, latency: u16) -> FbbActivePath {
    const idx = path_index & 0x07;
    var new_paths = active.paths;
    new_paths[idx] = fbb_path_status_update_metrics(new_paths[idx], throughput, latency);
    return FbbActivePath {
        .active_path = active.active_path,
        .bypass_path = active.bypass_path,
        .loopback_enabled = active.loopback_enabled,
        .paths = new_paths,
    };
}

// ============================================================================
// Validation Functions
// ============================================================================

// fbb_path_index_valid(index: u8) -> bool
// Check if path index is valid
pub fn fbb_path_index_valid(index: u8) -> bool {
    return index < FBB_PATH_COUNT;
}

// fbb_latency_valid(latency: u8) -> bool
// Check if latency is valid
pub fn fbb_latency_valid(latency: u8) -> bool {
    return latency >= FBB_LATENCY_MIN_CYCLES and latency <= FBB_LATENCY_MAX_CYCLES;
}

// fbb_bandwidth_valid(bandwidth: u32) -> bool
// Check if bandwidth is valid
pub fn fbb_bandwidth_valid(bandwidth: u32) -> bool {
    return bandwidth >= FBB_BANDWIDTH_MIN_MBPS and bandwidth <= FBB_BANDWIDTH_MAX_MBPS;
}

// fbb_path_config_valid(config: FbbPathConfig) -> bool
// Check if path config is valid
pub fn fbb_path_config_valid(config: FbbPathConfig) -> bool {
    return fbb_path_index_valid(config.path_index)
    try std.testing.expect(fbb_latency_valid(config.latency_cycles));
    try std.testing.expect(fbb_bandwidth_valid(config.bandwidth_mbps););
}

// ============================================================================
// Opcode Encoding/Decoding
// ============================================================================

// encode_fbb_cmd(op: u8, path: u8, param1: u8, param2: u8) -> u32
// Encode FBB command
pub fn encode_fbb_cmd(op: u8, path: u8, param1: u8, param2: u8) u32 {
    // Format: [OP:8][PATH:3][PARAM1:8][PARAM2:8][RES:5]
    const op_field : u32 = @as(u32, op) << 24;
    const path_field : u32 = @as(u32, path & 0x07) << 21;
    const param1_field : u32 = @as(u32, param1) << 13;
    const param2_field : u32 = @as(u32, param2) << 5;
    return op_field | path_field | param1_field | param2_field;
}

// decode_fbb_cmd(encoded: u32) -> struct { op: u8, path: u8, param1: u8, param2: u8 }
// Decode FBB command
pub fn decode_fbb_cmd(encoded: u32) -> struct { op: u8, path: u8, param1: u8, param2: u8 } {
    const op : u8 = @as(u8, @truncate((encoded >> 24) & 0xFF));
    const path : u8 = @as(u8, @truncate((encoded >> 21) & 0x07));
    const param1 : u8 = @as(u8, @truncate((encoded >> 13) & 0xFF));
    const param2 : u8 = @as(u8, @truncate((encoded >> 5) & 0xFF));
    return .{ .op = op, .path = path, .param1 = param1, .param2 = param2 };
}

