/// Index version
pub const INDEX_VERSION : u16 = 1;

/// Maximum index entries
pub const MAX_INDEX_ENTRIES : u16 = 65535;

/// Index block size in bytes
pub const INDEX_BLOCK_SIZE : u16 = 4096;

/// Delta compression threshold
pub const DELTA_COMPRESSION_THRESHOLD : u16 = 256;

/// Checkpoint retention count
pub const CHECKPOINT_RETENTION : u8 = 5;

/// Index entry type
pub const IndexEntryType = enum(u8) {
    data = 0,      // Regular data entry
    delta = 1,     // Compressed delta
    tombstone = 2,   // Deleted entry marker
    metadata = 3,   // Index metadata
};

/// Index operation status
pub const IndexStatus = enum(u8) {
    ok = 0,         // Operation succeeded
    conflict = 1,   // Version conflict
    not_found = 2,   // Key not found
    error = 3,       // Generic error
};

// ============================================================================
// Types
// ============================================================================

/// Index entry
pub const IndexEntry = struct {
    key : []u8,
    version : u64,
    value : []u8,
    entry_type : IndexEntryType,
    checksum : [32]u8,  // SHA-256 as hex string
    size_bytes : usize,
};

/// Index metadata
pub const IndexMetadata = struct {
    version : u16,
    entry_count : usize,
    last_checkpoint : SyncID,
    created_at_ms : u64,
    updated_at_ms : u64,
};

/// Index delta operation
pub const DeltaOp = struct {
    op_type : u8,  // 0=add, 1=remove, 2=modify
    key : []u8,
    value : ?[]u8,
    old_version : u64,
    new_version : u64,
};

/// Index block
pub const IndexBlock = struct {
    entries : []IndexEntry,
    block_index : u32,
    checksum : [32]u8,
};

/// Index state
pub const IndexState = struct {
    metadata : IndexMetadata,
    current_version : u64,
    blocks : []IndexBlock,
    checkpoints : []SyncCheckpoint,
};

/// Replay position
pub const ReplayPosition = struct {
    checkpoint_id : SyncID,
    operation_index : u32,
    timestamp_ms : u64,
};

/// Replay result
pub const ReplayResult = struct {
    applied_count : usize,
    skipped_count : usize,
    conflicts : usize,
    final_state : []u8,
};

/// Delta generation result
pub const DeltaResult = struct {
    delta : []DeltaOp,
    base_version : u64,
    target_version : u64,
    size_bytes : usize,
};

/// Index query
pub const IndexQuery = struct {
    key_pattern : []u8,
    min_version : ?u64,
    max_version : ?u64,
    limit : ?u16,
};

