    return IndexState{
        .metadata = IndexMetadata{
            .version = INDEX_VERSION,
            .entry_count = 0,
            .last_checkpoint = "",
            .created_at_ms = get_timestamp_ms(),
            .updated_at_ms = get_timestamp_ms(),
        },
        .current_version = 0,
        .blocks = &[_]IndexBlock{},
        .checkpoints = &[_]SyncCheckpoint{},
    };
}

