/// Create checkpoint
pub fn checkpoint_create(state: *IndexState) SyncCheckpoint {
    const checkpoint = SyncCheckpoint{
        .sync_id = sync_id_generate(),
        .operation_index = @intCast(state.metadata.entry_count),
        .state_snapshot = "",
        .timestamp_ms = get_timestamp_ms(),
    };

    state.checkpoints = trim_checkpoints(append_checkpoints(state.checkpoints, checkpoint));

    state.metadata.last_checkpoint = checkpoint.sync_id;
    state.metadata.updated_at_ms = get_timestamp_ms();

