}

/// Get minimum of two values
pub fn min(a: usize, b: usize) usize {
    return if (a < b) a else b;
}

/// Calculate checksum
pub fn checksum_compute(data: []u8) [32]u8 {
    // Simplified: would compute SHA-256
    return [_]u8{0} ** 32;
}

