    try std.testing.expect(block.block_index == 0);
}

test "sync_query_create" {
    const query = query_create("test");
    try std.testing.expect(std.mem.eql(query.key_pattern, "test"));
}

test "sync_query_with_version_range" {
    const query = query_with_version_range("test", 10, 100);
    try std.testing.expect(query.min_version.? == 10);
}

test "sync_replay_position_create" {
    const pos = replay_position_create(sync_id_generate(), 10);
    try std.testing.expect(pos.operation_index == 10);
}

test "sync_checkpoint_create" {
    const state = index_state_new();
    const checkpoint = checkpoint_create(&state);
    try std.testing.expect(checkpoint_count(state.checkpoints) > 0);
}

test "sync_trim_checkpoints" {
    var checkpoints : []SyncCheckpoint = &[_]SyncCheckpoint{};
    for (0..CHECKPOINT_RETENTION + 2) |i| {
        checkpoints = append_checkpoints(checkpoints, SyncCheckpoint{
            .sync_id = sync_id_generate(),
            .operation_index = @intCast(i),
            .state_snapshot = "",
            .timestamp_ms = get_timestamp_ms(),
        });
    }
    const trimmed = trim_checkpoints(checkpoints, checkpoints[checkpoints.len - 1]);
    try std.testing.expect(checkpoint_count(trimmed) == CHECKPOINT_RETENTION);
}

